#define MA_NO_VERSIONING
#define MINIAUDIO_IMPLEMENTATION
#include "decoder.h"
// Include the autogenerated header
#include "_cgo_export.h"

/**
 * Apply low-latency + high-quality options when the encoder implements them.
 * av_opt_set returns an error for unknown keys; that is ignored so the
 * same helper works for libx264, Media Foundation, NVENC, AMF, VAAPI, etc.
 */
static void apply_low_latency_encoder_opts(AVCodecContext *enc)
{
  void *priv = enc ? enc->priv_data : NULL;
  if (!priv)
    return;

  /* ---- Low-latency common options ---- */
  av_opt_set(priv, "tune", "zerolatency", 0);
  av_opt_set(priv, "profile", "main", 0);
  av_opt_set_int(priv, "realtime", 1, 0);
  av_opt_set_int(priv, "async_depth", 1, 0);
  av_opt_set(priv, "delay", "0", 0);
  av_opt_set_int(priv, "bf", 0, 0);       // reinforce no B-frames
  av_opt_set(priv, "forced-idr", "1", 0); // helpful after seeks (ignored if unsupported)

  /* libx264 uses named presets; NVENC uses p1–p7. Try software first. */
  if (av_opt_set(priv, "preset", "ultrafast", 0) < 0)
    av_opt_set(priv, "preset", "p4", 0); /* NVENC balanced quality */

  /* ---- Quality-based rate control (preferred) ---- */
  /* libx264 / x264rgb */
  av_opt_set(priv, "crf", "19", 0); /* high quality, still real-time capable */

  /* NVENC */
  av_opt_set(priv, "rc", "constqp", 0);
  av_opt_set_int(priv, "qp", 19, 0);
  av_opt_set(priv, "rc", "vbr", 0); /* fallback if constqp rejected */
  av_opt_set_int(priv, "cq", 19, 0);

  /* AMF */
  av_opt_set(priv, "rc", "cqp", 0);
  av_opt_set_int(priv, "qp_i", 18, 0);
  av_opt_set_int(priv, "qp_p", 20, 0);

  /* QSV */
  av_opt_set(priv, "look_ahead", "0", 0);        /* low latency */
  av_opt_set_int(priv, "global_quality", 19, 0); /* ICQ-style */
}

/**
 * Choose an encoder input format from the formats this codec actually
 * accepts. FFmpeg 8 deprecates AVCodec.pix_fmts; this uses
 * avcodec_get_supported_config() instead.
 *
 * Prefer the decoder's HW surface only when the encoder size already
 * matches (true zero-copy) AND the encoder can actually consume it.
 * h264_mf is known to produce garbage when given D3D11 surfaces, so it
 * is forced onto system-memory formats (NV12 / yuv420p).
 */
static enum AVPixelFormat pick_encoder_pix_fmt(AVCodecContext *enc, DemuxDecContext *dec_ctx)
{
  const enum AVPixelFormat *fmts = NULL;
  int ret = avcodec_get_supported_config(enc, NULL, AV_CODEC_CONFIG_PIX_FORMAT, 0,
                                         (const void **)&fmts, NULL);
  if (ret < 0 || !fmts)
    return AV_PIX_FMT_YUV420P;

  /* h264_mf cannot reliably consume D3D11 / D3D12 surfaces.
   * Always feed it system memory. */
  const char *codec_name = (enc->codec) ? enc->codec->name : NULL;
  bool force_software = (codec_name && strcmp(codec_name, "h264_mf") == 0);

  int same_size = !force_software &&
                  dec_ctx &&
                  dec_ctx->video_dec_ctx &&
                  enc->width == dec_ctx->video_dec_ctx->width &&
                  enc->height == dec_ctx->video_dec_ctx->height;

  if (same_size && dec_ctx->hw_pix_fmt != AV_PIX_FMT_NONE)
  {
    for (int i = 0; fmts[i] != AV_PIX_FMT_NONE; i++)
    {
      if (fmts[i] == dec_ctx->hw_pix_fmt)
        return dec_ctx->hw_pix_fmt;
    }
  }

  /* Prefer NV12, then yuv420p (safe software formats) */
  for (int i = 0; fmts[i] != AV_PIX_FMT_NONE; i++)
  {
    if (fmts[i] == AV_PIX_FMT_NV12)
      return AV_PIX_FMT_NV12;
  }
  for (int i = 0; fmts[i] != AV_PIX_FMT_NONE; i++)
  {
    if (fmts[i] == AV_PIX_FMT_YUV420P)
      return AV_PIX_FMT_YUV420P;
  }
  return fmts[0];
}

/**
 * Allocate, configure, and open one encoder. On any failure the context is
 * freed and *out_enc is left untouched.
 */
static int try_open_h264_encoder(DemuxDecContext *dec_ctx, const AVCodec *codec,
                                 int width, int height, AVCodecContext **out_enc)
{
  AVCodecContext *enc = avcodec_alloc_context3(codec);
  if (!enc)
    return AVERROR(ENOMEM);

  enc->width = width;
  enc->height = height;
  enc->pix_fmt = pick_encoder_pix_fmt(enc, dec_ctx);
  enc->time_base = (AVRational){1, 90000};
  enc->framerate = av_guess_frame_rate(
      dec_ctx->fmt_ctx,
      dec_ctx->fmt_ctx->streams[dec_ctx->video_stream_idx],
      NULL);
  if (enc->framerate.num == 0)
    enc->framerate = (AVRational){25, 1};

  /* ~1 second GOP, clamped to sensible limits.
   * Shorter GOPs improve seek responsiveness; longer ones help compression.
   */
  double fps = av_q2d(enc->framerate);
  if (fps < 1.0)
    fps = 30.0;

  int gop = (int)(fps + 0.5); // ≈ 1 second
  if (gop < 30)
    gop = 30;
  if (gop > 120)
    gop = 120;

  enc->gop_size = gop;
  enc->max_b_frames = 0;                     // Low latency
  enc->flags |= AV_CODEC_FLAG_GLOBAL_HEADER; // Required for fMP4 / MSE

  /* Always signal BT.709 SDR in the bitstream.
   * This is required so players treat the fMP4 as standard SDR. */
  enc->color_primaries = AVCOL_PRI_BT709;
  enc->color_trc = AVCOL_TRC_BT709;
  enc->colorspace = AVCOL_SPC_BT709;
  enc->color_range = AVCOL_RANGE_MPEG;

  /* Dynamic high-quality bitrate fallback.
   * Used by encoders that do not support CRF/CQ/CQP (e.g. h264_mf).
   * Quality-first formula based on pixels × fps.
   */
  {
    double megapixels = (double)(width * height) / 1000000.0;
    int target_bps;

    if (width >= 3840)
    {                                                          /* 4K / 8K */
      target_bps = (int)(megapixels * fps * 0.13 * 1000000.0); /* ~20-35 Mbps */
    }
    else if (width >= 2560)
    { /* 1440p */
      target_bps = (int)(megapixels * fps * 0.11 * 1000000.0);
    }
    else if (width >= 1920)
    {                                                          /* 1080p */
      target_bps = (int)(megapixels * fps * 0.10 * 1000000.0); /* ~8-14 Mbps */
    }
    else
    {
      target_bps = (int)(megapixels * fps * 0.09 * 1000000.0);
    }

    /* Sane clamps */
    if (target_bps < 3000000)
      target_bps = 3000000;
    if (target_bps > 45000000)
      target_bps = 45000000;

    enc->bit_rate = target_bps;
    LOG_INFO("C-ENC", "Dynamic bitrate fallback: %d kbps for %dx%d @ %.2f fps",
             target_bps / 1000, width, height, fps);
  }

  /* Share the decoder device ONLY when the encoder can actually consume
   * that surface. Never attach a D3D11 device to h264_mf. */
  bool is_mf = (strcmp(codec->name, "h264_mf") == 0);
  if (!is_mf &&
      dec_ctx->video_dec_ctx->hw_device_ctx &&
      enc->pix_fmt == dec_ctx->hw_pix_fmt)
  {
    enc->hw_device_ctx = av_buffer_ref(dec_ctx->video_dec_ctx->hw_device_ctx);
    if (!enc->hw_device_ctx)
    {
      avcodec_free_context(&enc);
      return AVERROR(ENOMEM);
    }
  }

  apply_low_latency_encoder_opts(enc);

  int ret = avcodec_open2(enc, codec, NULL);
  if (ret < 0)
  {
    avcodec_free_context(&enc);
    return ret;
  }

  *out_enc = enc;
  return 0;
}

/**
 * Map an AVFrame / AVCodecContext color matrix to a libswscale coefficient set.
 *
 * Using the same SWS_CS_DEFAULT table on both ends makes swscale treat the
 * convert as "matrix differs" for BT.2020 sources and insert
 * YUV → RGB → YUV. That is what stalled 4K HDR on Windows.
 *
 * Destination for this pipeline is always BT.709 (8-bit H.264 for MSE).
 */
static int sws_coeff_id_from_colorspace(enum AVColorSpace spc)
{
  switch (spc)
  {
  case AVCOL_SPC_BT709:
    return SWS_CS_ITU709;
  case AVCOL_SPC_BT470BG:
  case AVCOL_SPC_SMPTE170M:
    return SWS_CS_ITU601;
#ifdef SWS_CS_BT2020
  case AVCOL_SPC_BT2020_NCL:
  case AVCOL_SPC_BT2020_CL:
    return SWS_CS_BT2020;
#endif
  default:
    return SWS_CS_ITU709;
  }
}

/**
 * Returns true when the source should be treated as HDR.
 * Used to select higher-quality scaling and correct output tags.
 */
static bool is_hdr_source(const AVCodecContext *dec)
{
  if (!dec)
    return false;

  /* Transfer characteristics */
  if (dec->color_trc == AVCOL_TRC_SMPTE2084 ||  /* PQ */
      dec->color_trc == AVCOL_TRC_ARIB_STD_B67) /* HLG */
    return true;

  /* Primaries (BT.2020 is a strong signal even if TRC is missing) */
  if (dec->color_primaries == AVCOL_PRI_BT2020)
    return true;

  return false;
}

/**
 * Allocates, configures, and opens an H.264 video encoder context.
 *
 * Quality-first resolution policy:
 *   1. Try native resolution
 *   2. Fall back to 1440p → 1080p → 720p only when no encoder
 *      can open at the higher size.
 * Weak encoders (h264_mf, libx264) are never offered native/1440p –
 * they cannot sustain real-time 4K.
 *
 * Tries compiled-in hardware encoders first (quality-first portable order).
 * A candidate is used only when avcodec_find_encoder_by_name finds it and
 * avcodec_open2 succeeds on this GPU. libx264 is the last resort.
 *
 * @param dec_ctx       Pointer to the active DemuxDecContext.
 * @param out_enc_ctx   Pointer to receive the newly allocated AVCodecContext.
 *
 * @return 0 on success, or a negative FFmpeg error code on failure.
 */
static int init_h264_encoder(DemuxDecContext *dec_ctx, AVCodecContext **out_enc_ctx)
{
  if (!dec_ctx || !dec_ctx->video_dec_ctx)
    return AVERROR(EINVAL);

  /* Quality-first portable order.
   * Never hard-code preference for a particular machine.
   * We try to open each encoder at the target resolution;
   * first success wins.
   */
  static const char *const candidates[] = {
      "h264_nvenc",        // Best quality + latency (NVIDIA Turing+)
      "h264_amf",          // AMD
      "h264_qsv",          // Intel Quick Sync
      "h264_videotoolbox", // Apple
      "h264_d3d12va",      // Modern Windows HW path
      "h264_mf",           // Windows Media Foundation (fallback)
      "libx264",           // Software last resort
      NULL};

  const int src_width = dec_ctx->video_dec_ctx->width;
  const int src_height = dec_ctx->video_dec_ctx->height;
  const float aspect = (float)src_width / (float)src_height;

  /* Resolution ladder – highest quality first.
   * Only lower steps are added when native exceeds them.
   */
  typedef struct
  {
    int w, h;
    const char *label;
  } ResCandidate;

  ResCandidate resolutions[4];
  int res_count = 0;

  /* 1. Native */
  resolutions[res_count++] = (ResCandidate){src_width, src_height, "native"};

  /* 2. 1440p if native is larger */
  if (src_width > 2560 || src_height > 1440)
  {
    int w = 2560;
    int h = (int)(2560.0f / aspect);
    w &= ~1;
    h &= ~1;
    resolutions[res_count++] = (ResCandidate){w, h, "1440p"};
  }

  /* 3. 1080p if still larger */
  if (src_width > 1920 || src_height > 1080)
  {
    int w, h;
    if ((float)src_width / 1920.0f > (float)src_height / 1080.0f)
    {
      w = 1920;
      h = (int)(1920.0f / aspect);
    }
    else
    {
      h = 1080;
      w = (int)(1080.0f * aspect);
    }
    w &= ~1;
    h &= ~1;
    resolutions[res_count++] = (ResCandidate){w, h, "1080p"};
  }

  /* 4. 720p last resort */
  if (src_width > 1280 || src_height > 720)
  {
    int w = 1280;
    int h = (int)(1280.0f / aspect);
    w &= ~1;
    h &= ~1;
    resolutions[res_count++] = (ResCandidate){w, h, "720p"};
  }

  int last_err = AVERROR_ENCODER_NOT_FOUND;

  for (int r = 0; r < res_count; r++)
  {
    const int target_width = resolutions[r].w;
    const int target_height = resolutions[r].h;

    LOG_INFO("C-ENC", "Trying resolution %s (%dx%d) ...",
             resolutions[r].label, target_width, target_height);

    for (int i = 0; candidates[i]; i++)
    {
      const AVCodec *codec = avcodec_find_encoder_by_name(candidates[i]);
      if (!codec)
      {
        LOG_INFO("C-ENC", "  Encoder %s not present in this FFmpeg build", candidates[i]);
        continue;
      }

      /* Weak encoders cannot sustain real-time 4K / 1440p.
       * Skip high resolutions for them. */
      bool is_weak = (strcmp(candidates[i], "h264_mf") == 0 ||
                      strcmp(candidates[i], "libx264") == 0);
      if (is_weak && (target_width > 1920 || target_height > 1080))
      {
        LOG_INFO("C-ENC", "  Skipping %s at %dx%d (weak encoder, needs ≤1080p)",
                 candidates[i], target_width, target_height);
        continue;
      }

      AVCodecContext *enc = NULL;
      int ret = try_open_h264_encoder(dec_ctx, codec, target_width, target_height, &enc);
      if (ret < 0)
      {
        LOG_WARN("C-ENC", "  Encoder %s failed to open at %dx%d (%d); trying next",
                 candidates[i], target_width, target_height, ret);
        last_err = ret;
        continue;
      }

      /* Success */
      if (target_width != src_width || target_height != src_height)
      {
        LOG_INFO("C-ENC", "Downscaling from %dx%d → %dx%d (%s) for real-time capability",
                 src_width, src_height, target_width, target_height, resolutions[r].label);
      }
      else
      {
        LOG_INFO("C-ENC", "Using native resolution %dx%d", src_width, src_height);
      }

      LOG_INFO("C-ENC", "Selected encoder: %s  pix_fmt=%s  %dx%d",
               codec->name,
               av_get_pix_fmt_name(enc->pix_fmt),
               enc->width, enc->height);

      /* Final configuration summary – one clear line for operators */
      LOG_INFO("C-ENC", "FINAL: encoder=%s  %dx%d  pix_fmt=%s  bitrate=%lld kbps  gop=%d  max_b=%d",
               codec->name,
               enc->width, enc->height,
               av_get_pix_fmt_name(enc->pix_fmt),
               (long long)(enc->bit_rate / 1000),
               enc->gop_size,
               enc->max_b_frames);

      *out_enc_ctx = enc;
      return 0;
    }
  }

  LOG_ERROR("C-ENC", "No usable H.264 encoder found at any resolution (last error %d)", last_err);
  return last_err;
}

/**
 * Initializes the audio resampler context (SwrContext).
 *
 * Media files contain various sample rates (e.g., 44.1kHz, 48kHz), formats (e.g., s16, s32, flt),
 * and channel layouts (e.g., Mono, Stereo, 5.1). Miniaudio requires a consistent and predictable
 * hardware format to route audio cleanly.
 *
 * This function standardizes any incoming audio stream to:
 *   - Sample Rate: 48,000 Hz (48kHz Studio Quality)
 *   - Channels: 2 Channels (Stereo)
 *   - Format: 32-bit Floating Point (highly compatible with miniaudio & modern sound cards)
 *
 * @param ctx   Pointer to the active DemuxDecContext tracking the audio decoder.
 *
 * @return 0 on success, or a negative FFmpeg error code on failure.
 */
int init_audio_resampler(DemuxDecContext *ctx)
{
  int ret;

  // Set normalized audio properties
  ctx->target_sample_rate = 48000;
  av_channel_layout_default(&ctx->target_ch_layout, 2); // Force standard Stereo (L/R)
  // CRITICAL FIX: AAC native encoder requires AV_SAMPLE_FMT_FLTP (Planar)
  ctx->target_sample_fmt = AV_SAMPLE_FMT_FLTP; // Force 32-bit float format

  // Allocate and configure the SwrContext using the modern channel layout API.
  // This calculates transition coefficients between the source and target formats.
  ret = swr_alloc_set_opts2(
      &ctx->swr_ctx,
      &ctx->target_ch_layout,          // Output channel layout
      ctx->target_sample_fmt,          // Output sample format (Float32)
      ctx->target_sample_rate,         // Output sample rate (48000 Hz)
      &ctx->audio_dec_ctx->ch_layout,  // Input channel layout (from source codec)
      ctx->audio_dec_ctx->sample_fmt,  // Input sample format (from source codec)
      ctx->audio_dec_ctx->sample_rate, // Input sample rate (from source codec)
      0, NULL);                        // No extra log offset parameters

  // Ensure allocation succeeded before proceeding
  if (ret < 0 || !ctx->swr_ctx)
  {
    return (ret < 0) ? ret : AVERROR(ENOMEM);
  }

  // Initialize the resampler context with the configured parameters
  ret = swr_init(ctx->swr_ctx);
  if (ret < 0)
  {
    swr_free(&ctx->swr_ctx);
    return ret;
  }

  return 0;
}

/**
 * Callback to select hardware-accelerated pixel formats dynamically.
 *
 * FFmpeg invokes this from avcodec_open2 / the first decode. The decoder
 * proposes a list; we must return one entry from that list.
 *
 * We prefer the surface format recorded when the HW device was created
 * (ctx->hw_pix_fmt). That is the only OS-agnostic way to accept
 * videotoolbox, d3d11, d3d12, vaapi, cuda, qsv, etc. without naming them.
 *
 * avctx->opaque is the DemuxDecContext that owns this decoder. It is not
 * allocated here and must not be freed here.
 */
static enum AVPixelFormat get_hw_format(AVCodecContext *avctx, const enum AVPixelFormat *pix_fmts)
{
  DemuxDecContext *ctx = avctx ? (DemuxDecContext *)avctx->opaque : NULL;
  const enum AVPixelFormat *p;
  enum AVPixelFormat first_hw = AV_PIX_FMT_NONE;

  for (p = pix_fmts; *p != AV_PIX_FMT_NONE; p++)
  {
    const AVPixFmtDescriptor *desc = av_pix_fmt_desc_get(*p);
    LOG_INFO("C-DEC", "Decoder proposed pixel format: %s (%d)", av_get_pix_fmt_name(*p), *p);

    if (ctx && *p == ctx->hw_pix_fmt)
    {
      LOG_INFO("C-DEC", "Matched Hardware Pixel Format: %s", av_get_pix_fmt_name(*p));
      return *p;
    }

    if (first_hw == AV_PIX_FMT_NONE && desc && (desc->flags & AV_PIX_FMT_FLAG_HWACCEL))
      first_hw = *p;
  }

  if (first_hw != AV_PIX_FMT_NONE)
  {
    LOG_INFO("C-DEC", "Matched Hardware Pixel Format: %s", av_get_pix_fmt_name(first_hw));
    if (ctx)
      ctx->hw_pix_fmt = first_hw;
    return first_hw;
  }

  LOG_WARN("C-DEC", "No matching hardware pixel format found. Falling back to software format.");
  return *pix_fmts;
}

/**
 * Opens a media file, reads its metadata, and initializes the decoders
 * for both the primary video and audio streams.
 *
 * This function manages the safe, initial step-by-step pipeline discovery:
 *   1. Opens the media file container and parses headers.
 *   2. Extracts packet-level stream descriptors (resolution, codecs, sample rates).
 *   3. Locates the best video stream and opens its corresponding hardware-agnostic decoder.
 *   4. Locates the best audio stream, opens its decoder, and initializes the resampler.
 *
 * If any middle step fails, a unified "fail" label acts as an emergency sweep,
 * freeing partially allocated memory blocks to prevent structural leaks.
 *
 * @param ctx          Pointer to the uninitialized DemuxDecContext structure.
 * @param input_path   System file path to the source video (e.g., MKV, MP4).
 *
 * @return 0 on success, or a negative FFmpeg error code on failure.
 */
int open_input_and_decoders(DemuxDecContext *ctx, const char *input_path)
{
  int ret;
  ctx->fmt_ctx = NULL;
  ctx->video_stream_idx = -1;
  ctx->audio_stream_idx = -1;
  ctx->video_dec_ctx = NULL;
  ctx->audio_dec_ctx = NULL;
  ctx->swr_ctx = NULL;
  // Do not set it again in the passthrough short-circuit or the fail: path. AV_PIX_FMT_NONE is not a heap object.
  ctx->hw_pix_fmt = AV_PIX_FMT_NONE;

  // CAUTION: Disabled to avoid overriding the values set in Go
  // ctx->is_passthrough = 0;
  // ctx->container_type = CONTAINER_FMP4; // Default safe fallback

  av_log_set_level(AV_LOG_INFO); // or AV_LOG_WARNING for production

  // 1. Open the media file container and extract initial stream parameters
  ret = avformat_open_input(&ctx->fmt_ctx, input_path, NULL, NULL);
  if (ret < 0)
    return ret;

  // 2. Query the stream contents of the container to discover streams
  ret = avformat_find_stream_info(ctx->fmt_ctx, NULL);
  if (ret < 0)
    goto fail;

  // Discover stream indices for demuxing/remuxing
  const AVCodec *video_codec = NULL;
  ret = av_find_best_stream(ctx->fmt_ctx, AVMEDIA_TYPE_VIDEO, -1, -1, &video_codec, 0);
  if (ret >= 0)
  {
    ctx->video_stream_idx = ret;
  }

  const AVCodec *audio_codec = NULL;
  ret = av_find_best_stream(ctx->fmt_ctx, AVMEDIA_TYPE_AUDIO, -1, -1, &audio_codec, 0);
  if (ret >= 0)
  {
    ctx->audio_stream_idx = ret;
  }

  // --- PASSTHROUGH MODE SHORT-CIRCUIT ---
  // If passthrough is active, bypass decoder, hardware context, and resampler allocations completely.
  if (ctx->is_passthrough)
  {
    LOG_INFO("C-DEC", "Passthrough mode enabled — skipping decoder, HW acceleration, and resampler initialization.");
    log_input_stream_properties(ctx, input_path);
    return 0;
  }

  // 3. Find and configure the best Video Stream in the container
  if (ctx->video_stream_idx >= 0 && video_codec)
  {
    // Allocate raw codec context block
    ctx->video_dec_ctx = avcodec_alloc_context3(video_codec);
    if (!ctx->video_dec_ctx)
    {
      ret = AVERROR(ENOMEM);
      goto fail;
    }

    // Copy stream configurations (width, height, profiles) to the decoder context
    ret = avcodec_parameters_to_context(ctx->video_dec_ctx, ctx->fmt_ctx->streams[ctx->video_stream_idx]->codecpar);
    if (ret < 0)
      goto fail;

    // --- DIAGNOSTIC 1: Enumerate compiled HW types in libavutil ---
    LOG_INFO("C-DEC", "--- Available HW Device Types in FFmpeg Build ---");
    enum AVHWDeviceType iter_type = AV_HWDEVICE_TYPE_NONE;
    int hw_type_count = 0;
    while ((iter_type = av_hwdevice_iterate_types(iter_type)) != AV_HWDEVICE_TYPE_NONE)
    {
      LOG_INFO("C-DEC", "  [+] HW Device Supported: %s (enum %d)", av_hwdevice_get_type_name(iter_type), iter_type);
      hw_type_count++;
    }
    if (hw_type_count == 0)
    {
      LOG_WARN("C-DEC", "  [-] NO hardware device types are supported by this FFmpeg build!");
    }

    // --- DIAGNOSTIC 2: Query Codec HW Configurations ---
    LOG_INFO("C-DEC", "--- HW Configs for Codec '%s' ---", video_codec->name);
    for (int i = 0;; i++)
    {
      const AVCodecHWConfig *config = avcodec_get_hw_config(video_codec, i);
      if (!config)
        break;

      if (config->methods & AV_CODEC_HW_CONFIG_METHOD_HW_DEVICE_CTX)
      {
        LOG_INFO("C-DEC", "  [+] Codec supports HW Device: %s (PixFormat enum %d)",
                 av_hwdevice_get_type_name(config->device_type), config->pix_fmt);
      }
    }

    // --- HARDWARE ACCELERATION INITIALIZATION ---
    // Check if codec is unsupported by GPU hardware frameworks (VideoToolbox / D3D11VA / VAAPI)
    bool is_legacy_unsupported_hw_codec = (video_codec->id == AV_CODEC_ID_MPEG4 ||
                                           video_codec->id == AV_CODEC_ID_MPEG2VIDEO ||
                                           video_codec->id == AV_CODEC_ID_MSMPEG4V3);

    if (is_legacy_unsupported_hw_codec)
    {
      LOG_INFO("C-DEC", "[HWACCEL] Codec %s is unsupported by hardware frameworks. Forcing software decoder.",
               avcodec_get_name(video_codec->id));
    }
    else
    {
      /* Try device types in a stable, OS-neutral order. A type is used only
       * when this codec advertises HW_DEVICE_CTX for it and
       * av_hwdevice_ctx_create succeeds on this machine. */
      static const enum AVHWDeviceType preferred[] = {
          AV_HWDEVICE_TYPE_VIDEOTOOLBOX,
          AV_HWDEVICE_TYPE_D3D11VA,
          AV_HWDEVICE_TYPE_D3D12VA,
          AV_HWDEVICE_TYPE_CUDA,
          AV_HWDEVICE_TYPE_VAAPI,
          AV_HWDEVICE_TYPE_QSV,
          AV_HWDEVICE_TYPE_DXVA2,
          AV_HWDEVICE_TYPE_VULKAN,
          AV_HWDEVICE_TYPE_NONE};

      for (int p = 0; preferred[p] != AV_HWDEVICE_TYPE_NONE; p++)
      {
        const AVCodecHWConfig *match = NULL;
        for (int i = 0;; i++)
        {
          const AVCodecHWConfig *config = avcodec_get_hw_config(video_codec, i);
          if (!config)
            break;
          if ((config->methods & AV_CODEC_HW_CONFIG_METHOD_HW_DEVICE_CTX) &&
              config->device_type == preferred[p])
          {
            match = config;
            break;
          }
        }
        if (!match)
          continue;

        AVBufferRef *hw_device_ctx = NULL;
        int hw_ret = av_hwdevice_ctx_create(&hw_device_ctx, match->device_type, NULL, NULL, 0);
        if (hw_ret < 0)
        {
          LOG_WARN("C-DEC", "Failed to create hardware device context (%s). Trying next.",
                   av_hwdevice_get_type_name(match->device_type));
          continue;
        }

        /* Transfer ownership of the ref to the decoder context.
         * avcodec_free_context releases it. Do not unref hw_device_ctx after this. */
        ctx->video_dec_ctx->hw_device_ctx = hw_device_ctx;
        ctx->video_dec_ctx->opaque = ctx;
        ctx->hw_pix_fmt = match->pix_fmt;
        ctx->video_dec_ctx->get_format = get_hw_format;

        // CRITICAL FIX: Hardware decoders require single-threaded context configuration in FFmpeg.
        // Frame multithreading (FF_THREAD_FRAME) forces avcodec_open2 to silently disable hwaccel.
        ctx->video_dec_ctx->thread_count = 1;
        ctx->video_dec_ctx->thread_type = 0;

        LOG_INFO("C-DEC", "Successfully initialized hardware acceleration type: %d (%s)",
                 match->device_type, av_hwdevice_get_type_name(match->device_type));
        break;
      }
    }

    if (!ctx->video_dec_ctx->hw_device_ctx)
    {
      LOG_INFO("C-DEC", "No usable hardware decoder device; using software decode");

      // Multi-threaded configuration for platforms without hardware acceleration
      ctx->video_dec_ctx->thread_count = 0;
      ctx->video_dec_ctx->thread_type = FF_THREAD_FRAME | FF_THREAD_SLICE;
    }
    // --- END OF HARDWARE ACCELERATION INITIALIZATION ---

    ret = avcodec_open2(ctx->video_dec_ctx, video_codec, NULL);
    if (ret < 0)
      goto fail;
  }

  // 4. Find and configure the best Audio Stream in the container
  if (ctx->audio_stream_idx >= 0 && audio_codec)
  {
    // Allocate raw audio codec context block
    ctx->audio_dec_ctx = avcodec_alloc_context3(audio_codec);
    if (!ctx->audio_dec_ctx)
    {
      ret = AVERROR(ENOMEM);
      goto fail;
    }

    // Copy stream configurations (sample rate, bit-rate, channel layout) to the decoder context
    ret = avcodec_parameters_to_context(ctx->audio_dec_ctx, ctx->fmt_ctx->streams[ctx->audio_stream_idx]->codecpar);
    if (ret < 0)
      goto fail;

    // Initialize and open the audio decoder
    ret = avcodec_open2(ctx->audio_dec_ctx, audio_codec, NULL);
    if (ret < 0)
      goto fail;

    // Initialize swresample to normalize audio for miniaudio
    ret = init_audio_resampler(ctx);
    if (ret < 0)
      goto fail;
  }

  // Media probe banner
  log_input_stream_properties(ctx, input_path);

  return 0;

fail:
  // Rollback phase: cleanly close allocations in reverse order of initialization
  if (ctx->video_dec_ctx)
    avcodec_free_context(&ctx->video_dec_ctx);
  if (ctx->audio_dec_ctx)
    avcodec_free_context(&ctx->audio_dec_ctx);
  if (ctx->fmt_ctx)
    avformat_close_input(&ctx->fmt_ctx);
  return ret;
}

/**
 * Safely releases, closes, and tears down all resources managed inside
 * the DemuxDecContext, preventing memory leaks between presentation runs.
 *
 * Deallocation operates in strict alignment with ownership rules:
 *   1. Destroys the software resampler context.
 *   2. Deallocates and closes the video and audio decoders.
 *   3. Closes the container format context and releases file descriptors.
 *   4. Frees dynamically allocated channel layout structures.
 *
 * @param ctx   Pointer to the active DemuxDecContext struct to clean up.
 */
void free_demux_dec_context(DemuxDecContext *ctx)
{
  if (!ctx)
    return;

  // Free the resampler context
  if (ctx->swr_ctx)
    swr_free(&ctx->swr_ctx);

  // Free the video decoder resources
  if (ctx->video_dec_ctx)
    avcodec_free_context(&ctx->video_dec_ctx);

  // Free the audio decoder resources
  if (ctx->audio_dec_ctx)
    avcodec_free_context(&ctx->audio_dec_ctx);

  // Close format input and set context back to NULL
  if (ctx->fmt_ctx)
    avformat_close_input(&ctx->fmt_ctx);

  // Uninitialize the custom target channel layout to prevent leaking layout maps
  av_channel_layout_uninit(&ctx->target_ch_layout);
}

/**
 * Custom I/O write callback for the AVIOContext.
 *
 * This function is triggered by the FFmpeg muxer whenever a chunk or fragment
 * of the fragmented MP4 (fMP4) stream is finalized in memory. It immediately
 * passes the pointer and size of the generated binary buffer back to the Go
 * runtime using the registered Go callback function and integer user token.
 *
 * @param opaque    A pointer to the user-defined TranscodeContext struct.
 * @param buf       The raw binary buffer containing fMP4 data.
 * @param buf_size  The size of the buffer in bytes.
 *
 * @return The number of written bytes, representing success or custom error.
 */
static int write_to_memory_cb(void *opaque, const uint8_t *buf, int buf_size)
{
  TranscodeContext *ctx = (TranscodeContext *)opaque;
  if (!ctx)
    return buf_size;

  if (__atomic_load_n(&ctx->suppress_output, __ATOMIC_ACQUIRE))
    return buf_size;

  if (ctx->go_callback)
    ctx->go_callback((uint8_t *)buf, buf_size, ctx->go_user_token);

  return buf_size;
}

/**
 * Allocates and initializes an in-memory output Format Context for either
 * Fragmented MP4 (fMP4) or WebM Cluster streaming without disk I/O.
 *
 * Redirects all generated container bytes through 'write_to_memory_cb' directly to Go.
 *
 * @param out_fmt_ctx     Pointer to the uninitialized AVFormatContext pointer.
 * @param tx_ctx          Pointer to the Go callback routing context structure.
 * @param container_type  CONTAINER_FMP4 (0) or CONTAINER_WEBM (1).
 *
 * @return 0 on success, or a negative FFmpeg error code on failure.
 */
int init_passthrough_muxer(AVFormatContext **out_fmt_ctx, TranscodeContext *tx_ctx, PassthroughContainerType container_type)
{
  int ret;
  size_t avio_buf_size = 65536;
  uint8_t *avio_buf = NULL;
  AVIOContext *avio_ctx = NULL;

  if (container_type == CONTAINER_WEBM)
  {
    // Allocate WebM context for VP8/VP9/AV1 + Opus streams
    ret = avformat_alloc_output_context2(out_fmt_ctx, NULL, "webm", NULL);
    if (ret < 0 || !*out_fmt_ctx)
    {
      ret = avformat_alloc_output_context2(out_fmt_ctx, NULL, "matroska", NULL);
    }
    if (ret < 0 || !*out_fmt_ctx)
    {
      return ret;
    }

    // Configure WebM live cluster streaming flags for real-time MSE ingestion
    // 'live': Enables realtime stream mode (omits duration in header, writes simple blocks)
    av_opt_set((*out_fmt_ctx)->priv_data, "live", "1", 0);

    // 'cluster_time_limit': Force cluster creation every 1000ms (1 second) or on keyframes
    av_opt_set((*out_fmt_ctx)->priv_data, "cluster_time_limit", "1000", 0);
  }
  else
  {
    // Allocate Fragmented MP4 context for H.264/HEVC + AAC streams
    ret = avformat_alloc_output_context2(out_fmt_ctx, NULL, "mp4", NULL);
    if (ret < 0)
    {
      return ret;
    }

    // Configure fMP4 fragment flags required for MSE compatibility and delayed moov writing
    av_opt_set((*out_fmt_ctx)->priv_data, "movflags",
               "empty_moov+default_base_moof+frag_keyframe+separate_moof+negative_cts_offsets+omit_tfhd_offset", 0);
  }

  // FORCE SHIFT NEGATIVE PTS/DTS TO ZERO
  // Resolves Opus negative pre-roll timestamps (e.g. pts=-1360) crashing WebKit MSE
  av_opt_set(*out_fmt_ctx, "avoid_negative_ts", "make_non_negative", 0);

  avio_buf = (uint8_t *)av_malloc(avio_buf_size);
  if (!avio_buf)
  {
    avformat_free_context(*out_fmt_ctx);
    *out_fmt_ctx = NULL;
    return AVERROR(ENOMEM);
  }

  avio_ctx = avio_alloc_context(
      avio_buf,
      avio_buf_size,
      1,                  // Flag 1 sets the IO context to Write-Only mode
      tx_ctx,             // Passed into callbacks as 'opaque' parameter
      NULL,               // Read callback is unneeded for live output
      write_to_memory_cb, // Primary write interceptor callback
      NULL                // Seek callback omitted for live streams
  );

  if (!avio_ctx)
  {
    av_free(avio_buf);
    avformat_free_context(*out_fmt_ctx);
    *out_fmt_ctx = NULL;
    return AVERROR(ENOMEM);
  }

  (*out_fmt_ctx)->pb = avio_ctx;
  return 0;
}

/**
 * Backward-compatibility wrapper for transcode pipelines defaulting to fMP4.
 */
int init_fmp4_muxer(AVFormatContext **out_fmt_ctx, TranscodeContext *tx_ctx)
{
  return init_passthrough_muxer(out_fmt_ctx, tx_ctx, CONTAINER_FMP4);
}

/**
 * Formats and writes the initial fMP4 container headers to the memory context.
 *
 * This function injects the specific metadata options (`movflags`) required by
 * browser Media Source Extensions (MSE) to begin playback instantly.
 *
 * Options utilized:
 * - 'empty_moov': Writes a clean, frame-index-free structural header immediately.
 * - 'default_base_moof': Resolves frame offsets relative to fragment start points.
 * - 'frag_keyframe': Flushes a play-ready segment on every video keyframe.
 * - 'omit_tfhd_offset': Streamlines file metadata sizing for browser parsing.
 *
 * @param out_fmt_ctx  The output context allocated via init_fmp4_muxer.
 *
 * @return 0 on success, or a negative FFmpeg error code on failure.
 */
int write_fmp4_header(AVFormatContext *out_fmt_ctx)
{
  int ret;
  AVDictionary *opts = NULL;

  // Ensure FFmpeg fMP4 muxer explicitly handles negative CTS offsets
  ret = av_dict_set(&opts, "movflags", "empty_moov+default_base_moof+frag_keyframe+separate_moof+negative_cts_offsets+omit_tfhd_offset", 0);
  if (ret < 0)
  {
    return ret;
  }

  ret = avformat_write_header(out_fmt_ctx, &opts);
  av_dict_free(&opts);
  return ret;
}

/**
 * Safely releases and tears down all allocations associated with the memory-based
 * fMP4 multiplexing context, completely eliminating memory leaks.
 *
 * It extracts the dynamic buffer inside the AVIOContext and frees it in the correct
 * chronological order to prevent dangling pointer faults.
 *
 * @param out_fmt_ctx  The output context to be deallocated.
 */
void free_fmp4_muxer(AVFormatContext *out_fmt_ctx)
{
  if (!out_fmt_ctx)
  {
    return;
  }

  if (out_fmt_ctx->pb)
  {
    // Free the internal dynamic 4KB buffer inside the AVIO structure
    av_freep(&out_fmt_ctx->pb->buffer);
    // Free the custom IO context structure
    avio_context_free(&out_fmt_ctx->pb);
  }

  avformat_free_context(out_fmt_ctx);
}

int get_miniaudio_devices(NativeAudioDevice *devices, int max_devices)
{
  ma_context context;
  if (ma_context_init(NULL, 0, NULL, &context) != MA_SUCCESS)
  {
    return -1;
  }

  ma_device_info *pPlaybackDeviceInfos;
  ma_uint32 playbackDeviceCount;
  if (ma_context_get_devices(&context, &pPlaybackDeviceInfos, &playbackDeviceCount, NULL, NULL) != MA_SUCCESS)
  {
    ma_context_uninit(&context);
    return -2;
  }

  int count = 0;

  for (ma_uint32 i = 0; i < playbackDeviceCount && count < max_devices; i++)
  {
#if defined(__APPLE__) && (defined(MA_HAS_COREAUDIO) || defined(MA_SUPPORT_COREAUDIO) || defined(MINIAUDIO_H))
    // On macOS, extract the native CoreAudio AudioDeviceID from miniaudio's device ID union.
    // This provides a valid integer string (e.g. "74") required by CoreAudio's SetDefaultOutputDevice.
    uint32_t native_id = (uint32_t)(uintptr_t)pPlaybackDeviceInfos[i].id.coreaudio;
    snprintf(devices[count].id, sizeof(devices[count].id), "%u", native_id);
#else
    // On non-Apple platforms where the browser manages audio output via HTMLMediaElement.setSinkId(),
    // fallback to sequential string indices or keep standard miniaudio indexing.
    snprintf(devices[count].id, sizeof(devices[count].id), "%u", i);
#endif

    // Safely copy device name with guaranteed null-termination
    strncpy(devices[count].name, pPlaybackDeviceInfos[i].name, sizeof(devices[count].name) - 1);

    // Ensure null-termination
    devices[count].name[sizeof(devices[count].name) - 1] = '\0';

    // Set default flag
    devices[count].is_default = pPlaybackDeviceInfos[i].isDefault;

    // Increment the count at the end of the loop
    count++;
  }

  ma_context_uninit(&context);
  return count;
}

/**
 * Logs comprehensive metadata for all streams in the input media file.
 */
void log_input_stream_properties(DemuxDecContext *ctx, const char *file_path)
{
  if (!ctx || !ctx->fmt_ctx)
    return;

  LOG_INFO("C-PROBE", "================ MEDIA PROPERTIES ================");
  LOG_INFO("C-PROBE", "File: %s", file_path ? file_path : "Unknown");
  LOG_INFO("C-PROBE", "Format: %s (%s)",
           ctx->fmt_ctx->iformat ? ctx->fmt_ctx->iformat->name : "Unknown",
           ctx->fmt_ctx->iformat ? ctx->fmt_ctx->iformat->long_name : "Unknown");

  if (ctx->fmt_ctx->duration != AV_NOPTS_VALUE)
  {
    LOG_INFO("C-PROBE", "Duration: %.2f seconds", (double)ctx->fmt_ctx->duration / AV_TIME_BASE);
  }

  for (unsigned int i = 0; i < ctx->fmt_ctx->nb_streams; i++)
  {
    AVStream *st = ctx->fmt_ctx->streams[i];
    AVCodecParameters *par = st->codecpar;

    if (par->codec_type == AVMEDIA_TYPE_VIDEO)
    {
      const AVCodec *codec = avcodec_find_decoder(par->codec_id);
      const char *profile_str = avcodec_profile_name(par->codec_id, par->profile);
      const char *pix_fmt_str = av_get_pix_fmt_name(par->format);
      AVRational fps = av_guess_frame_rate(ctx->fmt_ctx, st, NULL);

      LOG_INFO("C-PROBE", "--- Video Stream [Index %d] ---", i);
      LOG_INFO("C-PROBE", "  Codec: %s (%s)",
               codec ? codec->name : "Unknown",
               codec ? codec->long_name : "Unknown");
      LOG_INFO("C-PROBE", "  Resolution: %dx%d", par->width, par->height);
      LOG_INFO("C-PROBE", "  Profile: %s (Value: %d)", profile_str ? profile_str : "Unknown/Baseline", par->profile);
      LOG_INFO("C-PROBE", "  Level: %d (%.1f)", par->level, (double)par->level / 10.0);
      LOG_INFO("C-PROBE", "  Pixel Format: %s", pix_fmt_str ? pix_fmt_str : "Unknown");
      LOG_INFO("C-PROBE", "  Framerate: %.2f fps", fps.den > 0 ? av_q2d(fps) : 0.0);
      LOG_INFO("C-PROBE", "  Timebase: %d/%d", st->time_base.num, st->time_base.den);
      LOG_INFO("C-PROBE", "  Bitrate: %lld kbps", (long long)(par->bit_rate / 1000));
    }
    else if (par->codec_type == AVMEDIA_TYPE_AUDIO)
    {
      const AVCodec *codec = avcodec_find_decoder(par->codec_id);
      const char *profile_str = avcodec_profile_name(par->codec_id, par->profile);
      char layout_buf[64] = {0};
      av_channel_layout_describe(&par->ch_layout, layout_buf, sizeof(layout_buf));

      LOG_INFO("C-PROBE", "--- Audio Stream [Index %d] ---", i);
      LOG_INFO("C-PROBE", "  Codec: %s (%s)",
               codec ? codec->name : "Unknown",
               codec ? codec->long_name : "Unknown");
      LOG_INFO("C-PROBE", "  Profile: %s (Value: %d)", profile_str ? profile_str : "Unknown", par->profile);
      LOG_INFO("C-PROBE", "  Sample Rate: %d Hz", par->sample_rate);
      LOG_INFO("C-PROBE", "  Channels: %d (%s)", par->ch_layout.nb_channels, layout_buf);
      LOG_INFO("C-PROBE", "  Format: %s", av_get_sample_fmt_name(par->format));
      LOG_INFO("C-PROBE", "  Timebase: %d/%d", st->time_base.num, st->time_base.den);
    }
  }
  LOG_INFO("C-PROBE", "==================================================");
}

int probe_media_properties(const char *file_path, CMediaProperties *props)
{
  if (!file_path || !props)
    return -1;

  // Zero out the target struct space safely
  memset(props, 0, sizeof(CMediaProperties));

  AVFormatContext *fmt_ctx = NULL;
  int ret = avformat_open_input(&fmt_ctx, file_path, NULL, NULL);
  if (ret < 0)
    return ret;

  ret = avformat_find_stream_info(fmt_ctx, NULL);
  if (ret < 0)
  {
    avformat_close_input(&fmt_ctx);
    return ret;
  }

  // 1. Populate Container Metadata
  if (fmt_ctx->iformat)
  {
    snprintf(props->format_name, sizeof(props->format_name), "%s", fmt_ctx->iformat->name ? fmt_ctx->iformat->name : "");
    snprintf(props->format_long_name, sizeof(props->format_long_name), "%s", fmt_ctx->iformat->long_name ? fmt_ctx->iformat->long_name : "");
  }
  if (fmt_ctx->duration != AV_NOPTS_VALUE)
  {
    props->duration_ms = (int64_t)(fmt_ctx->duration * 1000 / AV_TIME_BASE);
  }
  props->file_size_bytes = fmt_ctx->pb ? avio_size(fmt_ctx->pb) : 0;
  props->bit_rate = fmt_ctx->bit_rate;

  // 2. Extract Global Dict Tags Safely
  AVDictionaryEntry *tag = NULL;
  if ((tag = av_dict_get(fmt_ctx->metadata, "title", NULL, 0)))
    snprintf(props->title, sizeof(props->title), "%s", tag->value);
  if ((tag = av_dict_get(fmt_ctx->metadata, "artist", NULL, 0)))
    snprintf(props->author, sizeof(props->author), "%s", tag->value);
  else if ((tag = av_dict_get(fmt_ctx->metadata, "author", NULL, 0)))
    snprintf(props->author, sizeof(props->author), "%s", tag->value);
  if ((tag = av_dict_get(fmt_ctx->metadata, "album", NULL, 0)))
    snprintf(props->album, sizeof(props->album), "%s", tag->value);
  if ((tag = av_dict_get(fmt_ctx->metadata, "track", NULL, 0)))
    snprintf(props->track, sizeof(props->track), "%s", tag->value);
  if ((tag = av_dict_get(fmt_ctx->metadata, "genre", NULL, 0)))
    snprintf(props->genre, sizeof(props->genre), "%s", tag->value);
  if ((tag = av_dict_get(fmt_ctx->metadata, "creation_time", NULL, 0)))
    snprintf(props->creation_time, sizeof(props->creation_time), "%s", tag->value);

  // Raw codec string accumulators for unified MSE MIME generation
  char v_codec_raw[64] = {0};
  char a_codec_raw[64] = {0};

  // 3. Scan Across Stream Layout Arrays
  for (unsigned int i = 0; i < fmt_ctx->nb_streams; i++)
  {
    AVStream *stream = fmt_ctx->streams[i];
    AVCodecParameters *codec_par = stream->codecpar;

    // Handle Video Track
    if (codec_par->codec_type == AVMEDIA_TYPE_VIDEO && !props->has_video)
    {
      props->has_video = 1;
      props->width = codec_par->width;
      props->height = codec_par->height;

      const AVCodec *codec = avcodec_find_decoder(codec_par->codec_id);
      if (codec)
      {
        snprintf(props->video_codec, sizeof(props->video_codec), "%s", codec->name ? codec->name : "");
        snprintf(props->video_codec_long_name, sizeof(props->video_codec_long_name), "%s", codec->long_name ? codec->long_name : "");
      }

      // Framework Video Profile
      char profile_buf[64];
      avcodec_profile_name(codec_par->codec_id, codec_par->profile);
      snprintf(props->video_profile, sizeof(props->video_profile), "%s", avcodec_profile_name(codec_par->codec_id, codec_par->profile) ? avcodec_profile_name(codec_par->codec_id, codec_par->profile) : "Unknown");

      // Frame rate parsing
      AVRational frame_rate = av_guess_frame_rate(fmt_ctx, stream, NULL);
      if (frame_rate.den > 0)
      {
        props->framerate = av_q2d(frame_rate);
      }

      // Aspect Ratio tracking
      AVRational dar;
      av_reduce(&dar.num, &dar.den, codec_par->width * stream->sample_aspect_ratio.num, codec_par->height * stream->sample_aspect_ratio.den, 1024 * 1024);
      if (dar.num > 0 && dar.den > 0)
      {
        snprintf(props->aspect_ratio, sizeof(props->aspect_ratio), "%d:%d", dar.num, dar.den);
      }

      // Pixel specs and Color Spaces
      const char *pix_fmt_name = av_get_pix_fmt_name(codec_par->format);
      snprintf(props->pixel_format, sizeof(props->pixel_format), "%s", pix_fmt_name ? pix_fmt_name : "");
      snprintf(props->color_space, sizeof(props->color_space), "%s", av_color_space_name(codec_par->color_space) ? av_color_space_name(codec_par->color_space) : "");
      snprintf(props->color_transfer, sizeof(props->color_transfer), "%s", av_color_transfer_name(codec_par->color_trc) ? av_color_transfer_name(codec_par->color_trc) : "");
      snprintf(props->color_primaries, sizeof(props->color_primaries), "%s", av_color_primaries_name(codec_par->color_primaries) ? av_color_primaries_name(codec_par->color_primaries) : "");

      // RFC 6381 Candidate Video MIME Calculation
      if (codec_par->codec_id == AV_CODEC_ID_H264)
      {
        int profile = codec_par->profile != AV_PROFILE_UNKNOWN ? codec_par->profile : 0x4d;
        int level = codec_par->level != AV_LEVEL_UNKNOWN ? codec_par->level : 31;
        snprintf(v_codec_raw, sizeof(v_codec_raw), "avc1.%02x00%02x", profile, level);
        snprintf(props->candidate_video_mime, sizeof(props->candidate_video_mime), "video/mp4; codecs=\"%s\"", v_codec_raw);
      }
      else if (codec_par->codec_id == AV_CODEC_ID_HEVC)
      {
        int profile = codec_par->profile != AV_PROFILE_UNKNOWN ? codec_par->profile : 1;
        int level = codec_par->level != AV_LEVEL_UNKNOWN ? codec_par->level : 153;
        snprintf(v_codec_raw, sizeof(v_codec_raw), "hvc1.%d.4.L%d.B0", profile, level);
        snprintf(props->candidate_video_mime, sizeof(props->candidate_video_mime), "video/mp4; codecs=\"%s\"", v_codec_raw);
      }
      else if (codec_par->codec_id == AV_CODEC_ID_VP9)
      {
        snprintf(v_codec_raw, sizeof(v_codec_raw), "vp9");
        snprintf(props->candidate_video_mime, sizeof(props->candidate_video_mime), "video/webm; codecs=\"%s\"", v_codec_raw);
      }
      else if (codec_par->codec_id == AV_CODEC_ID_AV1)
      {
        snprintf(v_codec_raw, sizeof(v_codec_raw), "av01.0.08M.08");
        snprintf(props->candidate_video_mime, sizeof(props->candidate_video_mime), "video/mp4; codecs=\"%s\"", v_codec_raw);
      }
    }

    // Handle Audio Track
    else if (codec_par->codec_type == AVMEDIA_TYPE_AUDIO && !props->has_audio)
    {
      props->has_audio = 1;
      props->audio_channels = codec_par->ch_layout.nb_channels;
      props->sample_rate = codec_par->sample_rate;
      props->audio_bit_rate = codec_par->bit_rate;

      const AVCodec *codec = avcodec_find_decoder(codec_par->codec_id);
      if (codec)
      {
        snprintf(props->audio_codec, sizeof(props->audio_codec), "%s", codec->name ? codec->name : "");
        snprintf(props->audio_codec_long_name, sizeof(props->audio_codec_long_name), "%s", codec->long_name ? codec->long_name : "");
      }

      snprintf(props->audio_profile, sizeof(props->audio_profile), "%s", avcodec_profile_name(codec_par->codec_id, codec_par->profile) ? avcodec_profile_name(codec_par->codec_id, codec_par->profile) : "Unknown");

      // Unpack Channel layout descriptive labels natively
      char layout_buf[64];
      av_channel_layout_describe(&codec_par->ch_layout, layout_buf, sizeof(layout_buf));
      snprintf(props->channel_layout, sizeof(props->channel_layout), "%s", layout_buf);

      // RFC 6381 Candidate Audio MIME Calculation
      if (codec_par->codec_id == AV_CODEC_ID_AAC)
      {
        snprintf(a_codec_raw, sizeof(a_codec_raw), "mp4a.40.2");
        snprintf(props->candidate_audio_mime, sizeof(props->candidate_audio_mime), "audio/mp4; codecs=\"%s\"", a_codec_raw);
      }
      else if (codec_par->codec_id == AV_CODEC_ID_OPUS)
      {
        snprintf(a_codec_raw, sizeof(a_codec_raw), "opus");
        snprintf(props->candidate_audio_mime, sizeof(props->candidate_audio_mime), "audio/webm; codecs=\"%s\"", a_codec_raw);
      }
    }
  }

  // Combine Video and Audio candidate strings for Full MSE SourceBuffer descriptor
  if (v_codec_raw[0] != '\0' && a_codec_raw[0] != '\0')
  {
    const char *container = (strstr(props->candidate_video_mime, "video/webm") != NULL) ? "video/webm" : "video/mp4";
    snprintf(props->candidate_full_mime, sizeof(props->candidate_full_mime), "%s; codecs=\"%s, %s\"", container, v_codec_raw, a_codec_raw);
  }
  else if (props->candidate_video_mime[0] != '\0')
  {
    snprintf(props->candidate_full_mime, sizeof(props->candidate_full_mime), "%s", props->candidate_video_mime);
  }
  else if (props->candidate_audio_mime[0] != '\0')
  {
    snprintf(props->candidate_full_mime, sizeof(props->candidate_full_mime), "%s", props->candidate_audio_mime);
  }

  // Context demolition cleanup
  avformat_close_input(&fmt_ctx);
  return 0;
}

int extract_video_screenshot(const char *file_path, int64_t time_ms, uint8_t **out_buf, int *out_size)
{
  if (!file_path || !out_buf || !out_size)
    return -1;
  *out_buf = NULL;
  *out_size = 0;

  AVFormatContext *fmt_ctx = NULL;
  if (avformat_open_input(&fmt_ctx, file_path, NULL, NULL) < 0)
    return -1;
  if (avformat_find_stream_info(fmt_ctx, NULL) < 0)
  {
    avformat_close_input(&fmt_ctx);
    return -1;
  }

  // 1. Locate primary video track
  int video_stream_idx = -1;
  for (unsigned int i = 0; i < fmt_ctx->nb_streams; i++)
  {
    if (fmt_ctx->streams[i]->codecpar->codec_type == AVMEDIA_TYPE_VIDEO)
    {
      video_stream_idx = i;
      break;
    }
  }

  if (video_stream_idx == -1)
  {
    avformat_close_input(&fmt_ctx);
    return -2; // No video stream found
  }

  AVStream *stream = fmt_ctx->streams[video_stream_idx];
  AVCodecParameters *codec_par = stream->codecpar;

  // 2. Initialize input decoder context
  const AVCodec *decoder = avcodec_find_decoder(codec_par->codec_id);
  if (!decoder)
  {
    avformat_close_input(&fmt_ctx);
    return -3;
  }
  AVCodecContext *dec_ctx = avcodec_alloc_context3(decoder);
  avcodec_parameters_to_context(dec_ctx, codec_par);

  // Enable multi-threaded decoding to prevent 4K/HDR bottlenecks
  dec_ctx->thread_count = 0;
  dec_ctx->thread_type = FF_THREAD_FRAME | FF_THREAD_SLICE;

  if (avcodec_open2(dec_ctx, decoder, NULL) < 0)
  {
    avcodec_free_context(&dec_ctx);
    avformat_close_input(&fmt_ctx);
    return -4;
  }

  // 3. Compute stream specific seek timestamp bounds
  // Convert ms to stream time base units: units = (ms / 1000) / time_base
  int64_t seek_target = (int64_t)(time_ms * (int64_t)AV_TIME_BASE / 1000);
  seek_target = av_rescale_q(seek_target, AV_TIME_BASE_Q, stream->time_base);

  // Seek to the closest keyframe before or at the requested timeline point
  if (avformat_seek_file(fmt_ctx, video_stream_idx, INT64_MIN, seek_target, seek_target, AVSEEK_FLAG_BACKWARD) < 0)
  {
    avcodec_free_context(&dec_ctx);
    avformat_close_input(&fmt_ctx);
    return -5;
  }

  // Flush decoder state variables after a seek event
  avcodec_flush_buffers(dec_ctx);

  AVPacket *pkt = av_packet_alloc();
  AVFrame *frame = av_frame_alloc();
  int frame_decoded = 0;

  // 4. Extraction decoding pump loop
  while (av_read_frame(fmt_ctx, pkt) >= 0)
  {
    if (pkt->stream_index == video_stream_idx)
    {
      if (avcodec_send_packet(dec_ctx, pkt) >= 0)
      {
        if (avcodec_receive_frame(dec_ctx, frame) >= 0)
        {
          frame_decoded = 1;
          av_packet_unref(pkt);
          break;
        }
      }
    }
    av_packet_unref(pkt);
  }
  av_packet_free(&pkt);

  if (!frame_decoded)
  {
    av_frame_free(&frame);
    avcodec_free_context(&dec_ctx);
    avformat_close_input(&fmt_ctx);
    return -6; // Failed to decode a usable frame
  }

  // Setup SwsContext for color-space and bit-depth normalization (fixes HDR/10-bit color tinting & distortion)
  struct SwsContext *sws_ctx = sws_getContext(
      dec_ctx->width, dec_ctx->height, dec_ctx->pix_fmt,
      dec_ctx->width, dec_ctx->height, AV_PIX_FMT_YUV420P,
      SWS_BILINEAR, NULL, NULL, NULL);

  if (!sws_ctx)
  {
    av_frame_free(&frame);
    avcodec_free_context(&dec_ctx);
    avformat_close_input(&fmt_ctx);
    return -7;
  }

  int src_range = (dec_ctx->color_range == AVCOL_RANGE_JPEG);
  const int *src_inv_table = sws_getCoefficients(sws_coeff_id_from_colorspace(dec_ctx->colorspace));
  const int *dst_inv_table = sws_getCoefficients(SWS_CS_ITU709);
  sws_setColorspaceDetails(sws_ctx, src_inv_table, src_range, dst_inv_table, 0, 0, 1 << 16, 1 << 16);

  AVFrame *scaled_frame = av_frame_alloc();
  if (!scaled_frame)
  {
    sws_freeContext(sws_ctx);
    av_frame_free(&frame);
    avcodec_free_context(&dec_ctx);
    avformat_close_input(&fmt_ctx);
    return -7;
  }
  scaled_frame->format = AV_PIX_FMT_YUV420P;
  scaled_frame->width = dec_ctx->width;
  scaled_frame->height = dec_ctx->height;

  if (av_frame_get_buffer(scaled_frame, 32) < 0)
  {
    sws_freeContext(sws_ctx);
    av_frame_free(&scaled_frame);
    av_frame_free(&frame);
    avcodec_free_context(&dec_ctx);
    avformat_close_input(&fmt_ctx);
    return -7;
  }

  sws_scale(sws_ctx, (const uint8_t *const *)frame->data, frame->linesize,
            0, dec_ctx->height, scaled_frame->data, scaled_frame->linesize);

  // 5. Setup internal MJPEG image encoder pipeline
  const AVCodec *encoder = avcodec_find_encoder(AV_CODEC_ID_MJPEG);
  if (!encoder)
  {
    sws_freeContext(sws_ctx);
    av_frame_free(&scaled_frame);
    av_frame_free(&frame);
    avcodec_free_context(&dec_ctx);
    avformat_close_input(&fmt_ctx);
    return -7;
  }

  AVCodecContext *enc_ctx = avcodec_alloc_context3(encoder);
  enc_ctx->width = dec_ctx->width;
  enc_ctx->height = dec_ctx->height;
  // Set format matching standard MJPEG requirements (YUVJ420P or YUV420P depending on compilation)
  enc_ctx->pix_fmt = AV_PIX_FMT_YUVJ420P;
  enc_ctx->time_base = (AVRational){1, 25};

  if (avcodec_open2(enc_ctx, encoder, NULL) < 0)
  {
    enc_ctx->pix_fmt = AV_PIX_FMT_YUV420P; // Try fallback if YUVJ420P is constrained
    if (avcodec_open2(enc_ctx, encoder, NULL) < 0)
    {
      avcodec_free_context(&enc_ctx);
      sws_freeContext(sws_ctx);
      av_frame_free(&scaled_frame);
      av_frame_free(&frame);
      avcodec_free_context(&dec_ctx);
      avformat_close_input(&fmt_ctx);
      return -8;
    }
  }

  // Ensure our frame format matches encoder expectations or enforce color ranges
  scaled_frame->format = enc_ctx->pix_fmt;

  AVPacket *enc_pkt = av_packet_alloc();
  int encode_success = 0;

  if (avcodec_send_frame(enc_ctx, scaled_frame) >= 0)
  {
    if (avcodec_receive_packet(enc_ctx, enc_pkt) >= 0)
    {
      // Allocate memory boundary directly on the C heap to hold raw binary data safely
      *out_buf = (uint8_t *)av_malloc(enc_pkt->size);
      if (*out_buf)
      {
        memcpy(*out_buf, enc_pkt->data, enc_pkt->size);
        *out_size = enc_pkt->size;
        encode_success = 1;
      }
    }
  }

  // Final multi-context teardown and cleanup routines
  av_packet_free(&enc_pkt);
  sws_freeContext(sws_ctx);
  av_frame_free(&scaled_frame);
  av_frame_free(&frame);
  avcodec_free_context(&enc_ctx);
  avcodec_free_context(&dec_ctx);
  avformat_close_input(&fmt_ctx);

  return encode_success ? 0 : -9;
}

/**
 * Allocates and initializes an AAC audio encoder context and SwrContext resampler.
 * Used during video passthrough mode when the input audio track (e.g., PCM, FLAC, Vorbis)
 * is incompatible with browser MSE fMP4 requirements.
 *
 * @param dec_ctx      Primary demuxer/decoder context containing input audio parameters.
 * @param out_enc_ctx  Pointer to receive the initialized AAC encoder context.
 * @param out_swr_ctx  Pointer to receive the initialized SWR resampling context.
 *
 * @return 0 on success, or a negative FFmpeg error code on failure.
 */
static int init_aac_audio_transcoder(DemuxDecContext *dec_ctx, AVCodecContext **out_enc_ctx, SwrContext **out_swr_ctx)
{
  int ret = 0;
  const AVCodec *aac_codec = avcodec_find_encoder(AV_CODEC_ID_AAC);
  if (!aac_codec)
  {
    LOG_ERROR("C-AUDIO", "[HYBRID MUX] AAC encoder not found in local FFmpeg build");
    return AVERROR_ENCODER_NOT_FOUND;
  }

  AVCodecContext *enc_ctx = avcodec_alloc_context3(aac_codec);
  if (!enc_ctx)
  {
    return AVERROR(ENOMEM);
  }

  // Configure target AAC parameters optimized for MSE playback (48kHz FLTP Stereo @ 192kbps)
  enc_ctx->sample_rate = 48000;
  enc_ctx->sample_fmt = AV_SAMPLE_FMT_FLTP;
  enc_ctx->bit_rate = 192000;
  av_channel_layout_default(&enc_ctx->ch_layout, 2);
  enc_ctx->time_base = (AVRational){1, 48000};

  // Set global header flag if the output container format requires it (e.g. MP4/fMP4)
  if (dec_ctx->fmt_ctx->oformat && (dec_ctx->fmt_ctx->oformat->flags & AVFMT_GLOBALHEADER))
  {
    enc_ctx->flags |= AV_CODEC_FLAG_GLOBAL_HEADER;
  }

  ret = avcodec_open2(enc_ctx, aac_codec, NULL);
  if (ret < 0)
  {
    LOG_FFMPEG_ERR("C-AUDIO", "[HYBRID MUX] Failed to open AAC encoder context", ret);
    avcodec_free_context(&enc_ctx);
    return ret;
  }

  // Initialize SwrContext resampler to translate input audio format -> FLTP 48kHz Stereo
  SwrContext *swr_ctx = swr_alloc();
  if (!swr_ctx)
  {
    avcodec_free_context(&enc_ctx);
    return AVERROR(ENOMEM);
  }

  av_opt_set_chlayout(swr_ctx, "in_chlayout", &dec_ctx->audio_dec_ctx->ch_layout, 0);
  av_opt_set_int(swr_ctx, "in_sample_rate", dec_ctx->audio_dec_ctx->sample_rate, 0);
  av_opt_set_sample_fmt(swr_ctx, "in_sample_fmt", dec_ctx->audio_dec_ctx->sample_fmt, 0);

  av_opt_set_chlayout(swr_ctx, "out_chlayout", &enc_ctx->ch_layout, 0);
  av_opt_set_int(swr_ctx, "out_sample_rate", enc_ctx->sample_rate, 0);
  av_opt_set_sample_fmt(swr_ctx, "out_sample_fmt", enc_ctx->sample_fmt, 0);

  ret = swr_init(swr_ctx);
  if (ret < 0)
  {
    LOG_FFMPEG_ERR("C-AUDIO", "[HYBRID MUX] Failed to initialize SwrContext audio resampler", ret);
    swr_free(&swr_ctx);
    avcodec_free_context(&enc_ctx);
    return ret;
  }

  *out_enc_ctx = enc_ctx;
  *out_swr_ctx = swr_ctx;
  return 0;
}

int run_passthrough_mux_loop(DemuxDecContext *dec_ctx, uintptr_t go_token, PassthroughContainerType container_type)
{
  int ret = 0;
  TranscodeContext tx_ctx;
  AVFormatContext *out_fmt_ctx = NULL;
  AVPacket *pkt = NULL;

  int out_video_idx = -1;
  int out_audio_idx = -1;

  // Hybrid audio transcoding state
  int audio_needs_transcode = 0;
  AVCodecContext *aac_enc_ctx = NULL;
  SwrContext *audio_swr_ctx = NULL;
  AVAudioFifo *audio_fifo = NULL;
  AVFrame *raw_audio_frame = NULL;
  AVFrame *enc_audio_frame = NULL;
  AVPacket *enc_audio_pkt = NULL;
  uint8_t *resample_buf[2] = {NULL, NULL};
  int64_t audio_pts_counter = -1;

  tx_ctx.go_user_token = go_token;
  tx_ctx.go_callback = goStreamWriteCallback;
  tx_ctx.current_pts = 0.0;
  __atomic_store_n(&tx_ctx.suppress_output, 0, __ATOMIC_RELEASE);

  // 1. Initialize in-memory passthrough muxer context (fMP4 or WebM)
  ret = init_passthrough_muxer(&out_fmt_ctx, &tx_ctx, container_type);
  if (ret < 0)
  {
    LOG_FFMPEG_ERR("C-MUX", "[PASSTHROUGH] Failed to initialize passthrough muxer", ret);
    return ret;
  }

  // Force FFmpeg to shift negative pre-roll timestamps (e.g. pts=-88500) to start cleanly at 0
  if (out_fmt_ctx)
  {
    av_opt_set(out_fmt_ctx, "avoid_negative_ts", "make_non_negative", 0);
  }

  // Check if non-MSE audio needs live transcoding to AAC
  if (container_type == CONTAINER_FMP4 && dec_ctx->audio_stream_idx >= 0)
  {
    AVCodecParameters *a_par = dec_ctx->fmt_ctx->streams[dec_ctx->audio_stream_idx]->codecpar;

    if (a_par->codec_id != AV_CODEC_ID_AAC && a_par->codec_id != AV_CODEC_ID_OPUS)
    {
      audio_needs_transcode = 1;
      LOG_INFO("C-MUX", "[PASSTHROUGH] Non-MSE audio codec detected (%s). Enabling AAC audio transcode bridge.",
               avcodec_get_name(a_par->codec_id));

      if (!dec_ctx->audio_dec_ctx)
      {
        const AVCodec *a_dec = avcodec_find_decoder(a_par->codec_id);
        if (a_dec)
        {
          dec_ctx->audio_dec_ctx = avcodec_alloc_context3(a_dec);
          if (dec_ctx->audio_dec_ctx)
          {
            avcodec_parameters_to_context(dec_ctx->audio_dec_ctx, a_par);
            ret = avcodec_open2(dec_ctx->audio_dec_ctx, a_dec, NULL);
            if (ret < 0)
            {
              LOG_FFMPEG_ERR("C-MUX", "[HYBRID MUX] Failed to open input audio decoder", ret);
              audio_needs_transcode = 0;
            }
          }
        }
      }

      if (audio_needs_transcode && dec_ctx->audio_dec_ctx)
      {
        ret = init_aac_audio_transcoder(dec_ctx, &aac_enc_ctx, &audio_swr_ctx);
        if (ret < 0)
        {
          LOG_WARN("C-MUX", "[HYBRID MUX] Audio transcode bridge setup failed. Falling back to stream copy.");
          audio_needs_transcode = 0;
        }
        else
        {
          audio_fifo = av_audio_fifo_alloc(aac_enc_ctx->sample_fmt, 2, 32768);
          enc_audio_frame = av_frame_alloc();
          if (enc_audio_frame)
          {
            enc_audio_frame->nb_samples = aac_enc_ctx->frame_size;
            enc_audio_frame->format = aac_enc_ctx->sample_fmt;
            av_channel_layout_copy(&enc_audio_frame->ch_layout, &aac_enc_ctx->ch_layout);
            av_frame_get_buffer(enc_audio_frame, 0);
          }
          enc_audio_pkt = av_packet_alloc();
          raw_audio_frame = av_frame_alloc();
          av_samples_alloc(resample_buf, NULL, 2, 8192, AV_SAMPLE_FMT_FLTP, 0);
        }
      }
    }
  }

  // 2. Direct Video Stream Copy (No Decoder/Encoder Context Needed)
  if (dec_ctx->video_stream_idx >= 0)
  {
    AVStream *in_stream = dec_ctx->fmt_ctx->streams[dec_ctx->video_stream_idx];
    AVStream *out_stream = avformat_new_stream(out_fmt_ctx, NULL);
    if (!out_stream)
    {
      LOG_ERROR("C-MUX", "[PASSTHROUGH] Failed to allocate video stream");
      free_fmp4_muxer(out_fmt_ctx);
      return AVERROR(ENOMEM);
    }
    ret = avcodec_parameters_copy(out_stream->codecpar, in_stream->codecpar);
    if (ret < 0)
    {
      LOG_FFMPEG_ERR("C-MUX", "[PASSTHROUGH] Failed to copy video parameters", ret);
      free_fmp4_muxer(out_fmt_ctx);
      return ret;
    }
    out_stream->codecpar->codec_tag = 0;
    out_video_idx = out_stream->index;
  }

  // 3. Audio Stream Setup (Transcoded AAC vs Passthrough Copy)
  if (dec_ctx->audio_stream_idx >= 0)
  {
    AVStream *in_stream = dec_ctx->fmt_ctx->streams[dec_ctx->audio_stream_idx];
    AVStream *out_stream = avformat_new_stream(out_fmt_ctx, NULL);
    if (!out_stream)
    {
      LOG_ERROR("C-MUX", "[PASSTHROUGH] Failed to allocate audio stream");
      free_fmp4_muxer(out_fmt_ctx);
      return AVERROR(ENOMEM);
    }

    if (audio_needs_transcode && aac_enc_ctx)
    {
      ret = avcodec_parameters_from_context(out_stream->codecpar, aac_enc_ctx);
      if (ret < 0)
      {
        LOG_FFMPEG_ERR("C-MUX", "[PASSTHROUGH] Failed to copy AAC parameters to stream", ret);
        free_fmp4_muxer(out_fmt_ctx);
        return ret;
      }
    }
    else
    {
      ret = avcodec_parameters_copy(out_stream->codecpar, in_stream->codecpar);
      if (ret < 0)
      {
        LOG_FFMPEG_ERR("C-MUX", "[PASSTHROUGH] Failed to copy audio parameters", ret);
        free_fmp4_muxer(out_fmt_ctx);
        return ret;
      }
    }
    out_stream->codecpar->codec_tag = 0;
    out_audio_idx = out_stream->index;
  }

  // Write initial container header segment (fMP4 moov header OR WebM EBML header)
  if (container_type == CONTAINER_FMP4)
  {
    ret = write_fmp4_header(out_fmt_ctx);
  }
  else
  {
    ret = avformat_write_header(out_fmt_ctx, NULL);
  }
  if (ret < 0)
  {
    LOG_FFMPEG_ERR("C-MUX", "[PASSTHROUGH] Failed to write initial container header", ret);
    free_fmp4_muxer(out_fmt_ctx);
    return ret;
  }

  pkt = av_packet_alloc();
  if (!pkt)
  {
    LOG_ERROR("C-MUX", "[PASSTHROUGH] Failed to allocate packet");
    free_fmp4_muxer(out_fmt_ctx);
    return AVERROR(ENOMEM);
  }

  // Real-time pacing variables
  int64_t stream_start_time_us = av_gettime_relative();
  int64_t total_pause_us = 0;
  int64_t current_pause_start_us = 0;
  const int64_t READ_AHEAD_US = 5000000LL; // 5 seconds of runway (prevents high-bitrate MSE buffer quota eviction)
  int just_seeked = 0;
  int eof_reached = 0;
  int trailer_written = 0; // Prevents duplicate container trailer writes across seeks

  // Track previous stream DTS to enforce strict monotonicity for downstream MSE containers
  int64_t last_video_dts = AV_NOPTS_VALUE;
  int64_t last_audio_dts = AV_NOPTS_VALUE;

  // Baseline tracker for origin normalization
  int64_t first_video_dts = AV_NOPTS_VALUE;

  LOG_INFO("C-MUX", "Entering zero-copy passthrough streaming loop (Container Type: %d, Hybrid Audio Transcode: %d)", container_type, audio_needs_transcode);

  int wait_for_video_keyframe = 0;

  while (true)
  {
    // Atomic control flag checks from Go routine
    if (__atomic_load_n(&dec_ctx->stop_requested, __ATOMIC_ACQUIRE))
    {
      LOG_DEBUG("C-MUX", "[PASSTHROUGH] Stop requested. Exiting pipeline.");
      break;
    }

    // Handle seeking in passthrough mode
    if (__atomic_load_n(&dec_ctx->seek_requested, __ATOMIC_ACQUIRE))
    {
      int64_t target_ms = __atomic_load_n(&dec_ctx->seek_target_ms, __ATOMIC_ACQUIRE);
      int64_t seek_target = (int64_t)(target_ms * (int64_t)AV_TIME_BASE / 1000);
      int stream_idx = dec_ctx->video_stream_idx >= 0 ? dec_ctx->video_stream_idx : -1;

      if (stream_idx >= 0)
      {
        seek_target = av_rescale_q(seek_target, AV_TIME_BASE_Q, dec_ctx->fmt_ctx->streams[stream_idx]->time_base);
      }

      int seek_ret = av_seek_frame(dec_ctx->fmt_ctx, stream_idx, seek_target, AVSEEK_FLAG_BACKWARD);
      if (seek_ret >= 0)
      {
        LOG_INFO("C-SEEK", "[PASSTHROUGH] Executing backward seek to ms: %lld", (long long)target_ms);

        // Flushes internal demuxer packet queues so pre-seek packets
        // do not leak into the new container segment.
        avformat_flush(dec_ctx->fmt_ctx);

        if (audio_fifo)
        {
          av_audio_fifo_reset(audio_fifo);
        }

        if (audio_needs_transcode)
        {
          if (dec_ctx->audio_dec_ctx)
          {
            avcodec_flush_buffers(dec_ctx->audio_dec_ctx);
          }

          // Recreate AAC encoder context to purge stale lookahead frames and reset internal PTS
          if (aac_enc_ctx)
          {
            avcodec_free_context(&aac_enc_ctx);
            if (audio_swr_ctx)
            {
              swr_free(&audio_swr_ctx);
            }

            ret = init_aac_audio_transcoder(dec_ctx, &aac_enc_ctx, &audio_swr_ctx);
            if (ret < 0)
            {
              LOG_ERROR("C-SEEK", "[PASSTHROUGH] Failed to re-initialize AAC encoder after seek");
            }
          }
        }

        if (audio_fifo)
        {
          av_audio_fifo_reset(audio_fifo);
        }

        // Keep the original media clock. AAC encoder time_base is 1/48000.
        audio_pts_counter = target_ms * 48;

        // Re-initialize passthrough muxer context to reset DTS trackers.
        // The new ftyp/moov must not be forwarded to MSE (SourceBuffer is already initialized).
        if (out_fmt_ctx)
        {
          free_fmp4_muxer(out_fmt_ctx);
          out_fmt_ctx = NULL;
        }

        if (init_passthrough_muxer(&out_fmt_ctx, &tx_ctx, container_type) < 0)
        {
          LOG_ERROR("C-SEEK", "[PASSTHROUGH] Failed to re-initialize passthrough muxer after seek");
        }

        if (out_fmt_ctx)
        {
          av_opt_set(out_fmt_ctx, "avoid_negative_ts", "make_non_negative", 0);
        }

        // Re-map video stream
        if (dec_ctx->video_stream_idx >= 0 && out_fmt_ctx)
        {
          AVStream *out_stream = avformat_new_stream(out_fmt_ctx, NULL);
          if (out_stream)
          {
            if (avcodec_parameters_copy(out_stream->codecpar, dec_ctx->fmt_ctx->streams[dec_ctx->video_stream_idx]->codecpar) < 0)
            {
              LOG_ERROR("C-SEEK", "[PASSTHROUGH] Failed to map video parameters to new muxer");
            }
            out_stream->codecpar->codec_tag = 0;
            out_video_idx = out_stream->index;
          }
        }

        // Re-map audio stream
        if (dec_ctx->audio_stream_idx >= 0 && out_fmt_ctx)
        {
          AVStream *out_stream = avformat_new_stream(out_fmt_ctx, NULL);
          if (out_stream)
          {
            if (audio_needs_transcode && aac_enc_ctx)
            {
              if (avcodec_parameters_from_context(out_stream->codecpar, aac_enc_ctx) < 0)
              {
                LOG_ERROR("C-SEEK", "[PASSTHROUGH] Failed to map AAC parameters to new muxer");
              }
            }
            else
            {
              if (avcodec_parameters_copy(out_stream->codecpar, dec_ctx->fmt_ctx->streams[dec_ctx->audio_stream_idx]->codecpar) < 0)
              {
                LOG_ERROR("C-SEEK", "[PASSTHROUGH] Failed to map audio parameters to new muxer");
              }
            }
            out_stream->codecpar->codec_tag = 0;
            out_audio_idx = out_stream->index;
          }
        }

        if (out_fmt_ctx)
        {
          __atomic_store_n(&tx_ctx.suppress_output, 1, __ATOMIC_RELEASE);

          int hdr_ret = (container_type == CONTAINER_FMP4) ? write_fmp4_header(out_fmt_ctx) : avformat_write_header(out_fmt_ctx, NULL);
          if (hdr_ret < 0)
          {
            LOG_ERROR("C-SEEK", "[PASSTHROUGH] Failed to write container header after seek");
          }

          if (out_fmt_ctx->pb)
            avio_flush(out_fmt_ctx->pb);

          __atomic_store_n(&tx_ctx.suppress_output, 0, __ATOMIC_RELEASE);
        }

        stream_start_time_us = av_gettime_relative() - (target_ms * 1000LL);
        total_pause_us = 0;
        current_pause_start_us = 0;
        just_seeked = 1;
        wait_for_video_keyframe = (dec_ctx->video_stream_idx >= 0) ? 1 : 0;
        eof_reached = 0;
        trailer_written = 0;
        __atomic_store_n(&dec_ctx->backpressure_paused, 0, __ATOMIC_RELEASE);

        // Reset DTS state trackers for the new muxer session.
        // first_video_dts = 0 skips the start-of-file "rebase to origin" path
        // so post-seek packets keep their absolute timestamps.
        last_video_dts = AV_NOPTS_VALUE;
        last_audio_dts = AV_NOPTS_VALUE;
        first_video_dts = 0;

        extern void set_session_eof(uintptr_t token, int is_eof);
        set_session_eof(tx_ctx.go_user_token, 0);

        LOG_INFO("C-SEEK", "[PASSTHROUGH] Seek to %lld ms succeeded (absolute PTS preserved).", (long long)target_ms);
      }
      else
      {
        LOG_FFMPEG_ERR("C-SEEK", "[PASSTHROUGH] AVSeek execution failed", seek_ret);
      }

      __atomic_store_n(&dec_ctx->seek_requested, 0, __ATOMIC_RELEASE);
      continue;
    }

    // Handle pausing
    int user_paused = __atomic_load_n(&dec_ctx->paused, __ATOMIC_ACQUIRE);
    int bp_paused = __atomic_load_n(&dec_ctx->backpressure_paused, __ATOMIC_ACQUIRE);

    if (bp_paused || (user_paused && !just_seeked))
    {
      if (current_pause_start_us == 0)
        current_pause_start_us = av_gettime_relative();
      av_usleep(20000);
      continue;
    }
    else if (current_pause_start_us > 0)
    {
      total_pause_us += (av_gettime_relative() - current_pause_start_us);
      current_pause_start_us = 0;
    }

    // Read packet from demuxer
    if (!eof_reached)
    {
      ret = av_read_frame(dec_ctx->fmt_ctx, pkt);
      if (ret == AVERROR_EOF)
      {
        LOG_INFO("C-READ", "[PASSTHROUGH] EOF reached.");
        eof_reached = 1;

        if (audio_needs_transcode && aac_enc_ctx)
        {
          avcodec_send_frame(aac_enc_ctx, NULL);
          while (avcodec_receive_packet(aac_enc_ctx, enc_audio_pkt) >= 0)
          {
            av_packet_rescale_ts(enc_audio_pkt, aac_enc_ctx->time_base, out_fmt_ctx->streams[out_audio_idx]->time_base);
            enc_audio_pkt->stream_index = out_audio_idx;
            if (av_interleaved_write_frame(out_fmt_ctx, enc_audio_pkt) < 0)
            {
              LOG_WARN("C-MUX", "[HYBRID MUX] Failed to write flushed audio packet");
            }
            av_packet_unref(enc_audio_pkt);
          }
        }

        if (out_fmt_ctx && !trailer_written)
        {
          av_write_trailer(out_fmt_ctx);
          trailer_written = 1;
        }

        extern void set_session_eof(uintptr_t token, int is_eof);
        set_session_eof(tx_ctx.go_user_token, 1);
      }
      else if (ret < 0)
      {
        LOG_FFMPEG_ERR("C-READ", "[PASSTHROUGH] Fatal packet read error", ret);
        break;
      }
    }

    if (eof_reached)
    {
      av_usleep(100000);
      continue;
    }

    // Post-seek video keyframe guard: drop audio and non-keyframe video packets
    // until the demuxer delivers the first video IDR frame.
    if (wait_for_video_keyframe && dec_ctx->video_stream_idx >= 0)
    {
      if (pkt->stream_index == dec_ctx->video_stream_idx)
      {
        if (pkt->flags & AV_PKT_FLAG_KEY)
        {
          wait_for_video_keyframe = 0;
        }
        else
        {
          av_packet_unref(pkt);
          continue; // Drop lead-in P/B video frames
        }
      }
      else
      {
        av_packet_unref(pkt);
        continue; // Drop audio packets preceding the first post-seek video keyframe
      }
    }

    // HYBRID AUDIO TRANSCODE PATH
    if (pkt->stream_index == dec_ctx->audio_stream_idx && audio_needs_transcode && aac_enc_ctx && audio_fifo)
    {
      // Start-of-file only. After seek, audio_pts_counter is already at target*48.
      if (audio_pts_counter < 0 && pkt->pts != AV_NOPTS_VALUE)
      {
        AVStream *in_audio_stream = dec_ctx->fmt_ctx->streams[dec_ctx->audio_stream_idx];
        double pkt_pts_sec = pkt->pts * av_q2d(in_audio_stream->time_base);
        if (pkt_pts_sec < 0.0)
          pkt_pts_sec = 0.0;

        // Pre-pad lead-in audio gap with silent PCM FLTP samples to anchor audio start to 0.0s
        int silence_samples = (int)(pkt_pts_sec * 48000.0);
        if (silence_samples > 0)
        {
          LOG_INFO("C-AUDIO", "[HYBRID MUX] Pre-padding audio gap with %d silent samples (%.3f sec)",
                   silence_samples, pkt_pts_sec);

          // Zero out planar Float32 channel buffers (IEEE 754 float 0.0f = 0x00)
          memset(resample_buf[0], 0, 8192 * sizeof(float));
          memset(resample_buf[1], 0, 8192 * sizeof(float));

          int samples_remaining = silence_samples;
          while (samples_remaining > 0)
          {
            int chunk = (samples_remaining > 8192) ? 8192 : samples_remaining;
            int realloc_ret = av_audio_fifo_realloc(audio_fifo, av_audio_fifo_size(audio_fifo) + chunk);
            if (realloc_ret < 0)
            {
              LOG_FFMPEG_ERR("C-AUDIO", "[HYBRID MUX] Failed to reallocate audio FIFO for silence padding", realloc_ret);
              break;
            }
            av_audio_fifo_write(audio_fifo, (void **)resample_buf, chunk);
            samples_remaining -= chunk;
          }
        }

        // Force baseline counter to begin strictly at PTS = 0
        audio_pts_counter = 0;
      }

      if (avcodec_send_packet(dec_ctx->audio_dec_ctx, pkt) >= 0)
      {
        while (avcodec_receive_frame(dec_ctx->audio_dec_ctx, raw_audio_frame) >= 0)
        {
          int out_samples = swr_convert(audio_swr_ctx, resample_buf, 8192,
                                        (const uint8_t **)raw_audio_frame->data, raw_audio_frame->nb_samples);
          if (out_samples > 0)
          {
            int realloc_ret = av_audio_fifo_realloc(audio_fifo, av_audio_fifo_size(audio_fifo) + out_samples);
            if (realloc_ret < 0)
            {
              LOG_FFMPEG_ERR("C-MUX", "[HYBRID MUX] Could not reallocate audio FIFO", realloc_ret);
              __atomic_store_n(&dec_ctx->stop_requested, 1, __ATOMIC_RELEASE);
              break;
            }

            int write_ret = av_audio_fifo_write(audio_fifo, (void **)resample_buf, out_samples);
            if (write_ret < 0)
            {
              LOG_FFMPEG_ERR("C-MUX", "[HYBRID MUX] Failed to write into audio FIFO", write_ret);
              __atomic_store_n(&dec_ctx->stop_requested, 1, __ATOMIC_RELEASE);
              break;
            }
          }

          while (av_audio_fifo_size(audio_fifo) >= aac_enc_ctx->frame_size)
          {
            int read_ret = av_audio_fifo_read(audio_fifo, (void **)enc_audio_frame->data, aac_enc_ctx->frame_size);
            if (read_ret < 0)
            {
              LOG_FFMPEG_ERR("C-MUX", "[HYBRID MUX] Failed to read from audio FIFO", read_ret);
              break;
            }

            if (audio_pts_counter < 0)
              audio_pts_counter = 0;
            enc_audio_frame->pts = audio_pts_counter;
            audio_pts_counter += aac_enc_ctx->frame_size;

            if (avcodec_send_frame(aac_enc_ctx, enc_audio_frame) >= 0)
            {
              while (avcodec_receive_packet(aac_enc_ctx, enc_audio_pkt) >= 0)
              {
                av_packet_rescale_ts(enc_audio_pkt, aac_enc_ctx->time_base,
                                     out_fmt_ctx->streams[out_audio_idx]->time_base);
                enc_audio_pkt->stream_index = out_audio_idx;

                LOG_DEBUG("C-MUX", "[HYBRID MUX] Writing AUDIO packet pts=%lld size=%d",
                          (long long)enc_audio_pkt->pts, enc_audio_pkt->size);

                if (av_interleaved_write_frame(out_fmt_ctx, enc_audio_pkt) < 0)
                {
                  LOG_ERROR("C-MUX", "[HYBRID MUX] Failed to write interleaved audio packet. Halting.");
                  __atomic_store_n(&dec_ctx->stop_requested, 1, __ATOMIC_RELEASE);
                }
                av_packet_unref(enc_audio_pkt);
              }
            }
          }
        }
      }
      av_packet_unref(pkt);
      continue;
    }

    // Force audio FIFO conversion pass before processing video frames
    if (pkt->stream_index == dec_ctx->video_stream_idx && audio_needs_transcode && audio_fifo && aac_enc_ctx)
    {
      while (av_audio_fifo_size(audio_fifo) >= aac_enc_ctx->frame_size)
      {
        if (av_audio_fifo_read(audio_fifo, (void **)enc_audio_frame->data, aac_enc_ctx->frame_size) >= 0)
        {
          if (audio_pts_counter < 0)
            audio_pts_counter = 0;
          enc_audio_frame->pts = audio_pts_counter;
          audio_pts_counter += aac_enc_ctx->frame_size;

          if (avcodec_send_frame(aac_enc_ctx, enc_audio_frame) >= 0)
          {
            while (avcodec_receive_packet(aac_enc_ctx, enc_audio_pkt) >= 0)
            {
              av_packet_rescale_ts(enc_audio_pkt, aac_enc_ctx->time_base, out_fmt_ctx->streams[out_audio_idx]->time_base);
              enc_audio_pkt->stream_index = out_audio_idx;
              av_interleaved_write_frame(out_fmt_ctx, enc_audio_pkt);
              av_packet_unref(enc_audio_pkt);
            }
          }
        }
      }
    }

    // Determine target output stream index for zero-copy passthrough streams
    int target_out_idx = -1;
    AVStream *in_stream = NULL;

    if (pkt->stream_index == dec_ctx->video_stream_idx)
    {
      target_out_idx = out_video_idx;
      in_stream = dec_ctx->fmt_ctx->streams[dec_ctx->video_stream_idx];
    }
    else if (pkt->stream_index == dec_ctx->audio_stream_idx)
    {
      target_out_idx = out_audio_idx;
      in_stream = dec_ctx->fmt_ctx->streams[dec_ctx->audio_stream_idx];
    }

    // Perform packet copy and real-time pacing
    if (target_out_idx >= 0 && in_stream)
    {
      AVStream *out_stream = out_fmt_ctx->streams[target_out_idx];

      // Fall back to DTS if PTS is unassigned in container packets (e.g., MOV/MP4 demuxing)
      int64_t pacing_pts = (pkt->pts != AV_NOPTS_VALUE) ? pkt->pts : pkt->dts;
      double calculated_pts = (pacing_pts != AV_NOPTS_VALUE) ? pacing_pts * av_q2d(in_stream->time_base) : 0.0;
      int64_t pkt_time_us = (int64_t)(calculated_pts * 1000000.0);

      extern void set_session_pts(uintptr_t token, double pts);
      set_session_pts(tx_ctx.go_user_token, calculated_pts);

      int interrupted = 0;

      if (just_seeked)
      {
        stream_start_time_us = av_gettime_relative() - pkt_time_us;
        just_seeked = 0;
      }
      else
      {
        while (true)
        {
          if (__atomic_load_n(&dec_ctx->stop_requested, __ATOMIC_ACQUIRE) ||
              __atomic_load_n(&dec_ctx->seek_requested, __ATOMIC_ACQUIRE) ||
              __atomic_load_n(&dec_ctx->paused, __ATOMIC_ACQUIRE))
          {
            interrupted = 1;
            break;
          }

          int64_t elapsed_us = av_gettime_relative() - stream_start_time_us - total_pause_us;
          if (pkt_time_us > elapsed_us + READ_AHEAD_US)
            av_usleep(5000);
          else
            break;
        }
      }

      if (__atomic_load_n(&dec_ctx->seek_requested, __ATOMIC_ACQUIRE))
      {
        av_packet_unref(pkt);
        continue;
      }

      if (!interrupted)
      {
        // Establish initial DTS baseline on first video frame after start/seek
        if (pkt->stream_index == dec_ctx->video_stream_idx && first_video_dts == AV_NOPTS_VALUE)
        {
          first_video_dts = (pkt->dts != AV_NOPTS_VALUE) ? pkt->dts : ((pkt->pts != AV_NOPTS_VALUE) ? pkt->pts : 0);
        }

        // Shift timestamp baseline to zero relative to initial post-seek/start video DTS
        if (first_video_dts != AV_NOPTS_VALUE)
        {
          if (pkt->stream_index == dec_ctx->video_stream_idx)
          {
            if (pkt->pts != AV_NOPTS_VALUE)
              pkt->pts -= first_video_dts;
            if (pkt->dts != AV_NOPTS_VALUE)
              pkt->dts -= first_video_dts;
          }
          else if (pkt->stream_index == dec_ctx->audio_stream_idx && !audio_needs_transcode)
          {
            // Convert video baseline DTS to audio timebase for passthrough audio alignment
            AVStream *v_st = dec_ctx->fmt_ctx->streams[dec_ctx->video_stream_idx];
            int64_t a_base_dts = av_rescale_q(first_video_dts, v_st->time_base, in_stream->time_base);
            if (pkt->pts != AV_NOPTS_VALUE)
              pkt->pts -= a_base_dts;
            if (pkt->dts != AV_NOPTS_VALUE)
              pkt->dts -= a_base_dts;
          }
        }

        // Rescale timestamps from input demuxer timebase to output stream timebase
        av_packet_rescale_ts(pkt, in_stream->time_base, out_stream->time_base);
        pkt->stream_index = target_out_idx;

        // Enforce strict DTS monotonicity and PTS >= DTS rules for B-frames
        int64_t *last_dts_ptr = (target_out_idx == out_video_idx) ? &last_video_dts : &last_audio_dts;

        // Fallback for containers (like MKV) that do not set explicit DTS on packets
        if (pkt->dts == AV_NOPTS_VALUE)
        {
          if (*last_dts_ptr != AV_NOPTS_VALUE)
            pkt->dts = *last_dts_ptr + 1;
          else
            pkt->dts = (pkt->pts != AV_NOPTS_VALUE) ? pkt->pts : 0;
        }

        // Prevent negative DTS values after rescaling
        if (pkt->dts < 0)
        {
          pkt->dts = 0;
        }

        // Fix B-frame out-of-order DTS from MKV demuxer
        if (*last_dts_ptr != AV_NOPTS_VALUE && pkt->dts <= *last_dts_ptr)
        {
          pkt->dts = *last_dts_ptr + 1;
        }

        // Ensure Composition Time Offset (PTS - DTS) is never negative
        if (pkt->pts != AV_NOPTS_VALUE && pkt->pts < pkt->dts)
        {
          pkt->pts = pkt->dts;
        }

        *last_dts_ptr = pkt->dts;

        LOG_DEBUG("C-MUX", "[PASSTHROUGH] Writing packet stream=%d pts=%lld dts=%lld size=%d",
                  target_out_idx, (long long)pkt->pts, (long long)pkt->dts, pkt->size);

        if (av_interleaved_write_frame(out_fmt_ctx, pkt) < 0)
        {
          LOG_ERROR("C-MUX", "[PASSTHROUGH] Failed to write packet to output. Halting.");
          __atomic_store_n(&dec_ctx->stop_requested, 1, __ATOMIC_RELEASE);
        }
      }
    }

    av_packet_unref(pkt);
  }

  LOG_INFO("C-MUX", "[PASSTHROUGH] Commencing final teardown of passthrough pipeline.");

  if (pkt)
    av_packet_free(&pkt);
  if (raw_audio_frame)
    av_frame_free(&raw_audio_frame);
  if (enc_audio_frame)
    av_frame_free(&enc_audio_frame);
  if (enc_audio_pkt)
    av_packet_free(&enc_audio_pkt);
  if (audio_fifo)
    av_audio_fifo_free(audio_fifo);
  if (resample_buf[0])
    av_freep(&resample_buf[0]);
  if (aac_enc_ctx)
    avcodec_free_context(&aac_enc_ctx);
  if (audio_swr_ctx)
    swr_free(&audio_swr_ctx);
  if (dec_ctx->audio_dec_ctx && audio_needs_transcode)
  {
    avcodec_free_context(&dec_ctx->audio_dec_ctx);
  }
  if (out_fmt_ctx)
    free_fmp4_muxer(out_fmt_ctx);

  return ret;
}

/**
 * Main Live Transcoding & Streaming Execution Pipeline.
 *
 * Handles real-time demuxing, video scaling/encoding (H.264), audio resampling/encoding (AAC),
 * and live fMP4 muxing for browser MSE streaming.
 *
 * Key Pipeline Architectural Responsibilities:
 *  - Short-circuits to `run_passthrough_mux_loop` when `is_passthrough` is enabled.
 *  - Passthrough H.264 video streams directly when re-encoding is unneeded, or forces low-latency
 *    H.264 encoding with hardware surface extraction (VideoToolbox / VAAPI / D3D11 / CUDA).
 *  - Transcodes and resamples audio to 48kHz FLTP stereo AAC, maintaining strict sample FIFO sizing.
 *  - Enforces real-time wall-clock pacing to throttle downstream buffer generation to a 20-second window.
 *  - Handles dynamic thread-safe seeking, encoder context recreation, and graceful pipeline flushing at EOF.
 *
 * @param dec_ctx   Demuxer and decoder pipeline context.
 * @param go_token  Opaque pointer token passed to Go callbacks for WebSocket chunk routing.
 *
 * @return 0 on successful stream completion or negative FFmpeg error code on failure.
 */
int run_streaming_mux_and_play(DemuxDecContext *dec_ctx, uintptr_t go_token)
{
  // ZERO-COPY PASSTHROUGH SHORT-CIRCUIT
  if (dec_ctx->is_passthrough)
  {
    LOG_INFO("C-MUX", "Routing execution to Zero-Copy Passthrough pipeline (Container Type: %d)", dec_ctx->container_type);
    return run_passthrough_mux_loop(dec_ctx, go_token, dec_ctx->container_type);
  }

  int ret;
  TranscodeContext tx_ctx;
  AVFormatContext *out_fmt_ctx = NULL;
  AVPacket *pkt = NULL;
  AVFrame *frame = NULL;

  // Hoist all structural variables to the top to ensure safe goto cleanup
  int out_video_idx = -1;
  bool need_video_reencode = false;
  AVCodecContext *h264_enc_ctx = NULL;
  struct SwsContext *sws_ctx = NULL;
  AVFrame *enc_video_frame = NULL;
  AVPacket *enc_video_pkt = NULL;

  int out_audio_idx = -1;
  int audio_needs_transcode = 0;
  int wait_for_video_keyframe = 0;
  AVCodecContext *aac_enc_ctx = NULL;
  SwrContext *audio_swr_ctx = NULL;
  AVAudioFifo *fifo = NULL;
  AVFrame *enc_frame = NULL;
  AVPacket *enc_pkt = NULL;
  uint8_t *resample_buf[2] = {NULL, NULL};
  int64_t audio_pts_counter = -1; // Allows clean reset after seek

  tx_ctx.go_user_token = go_token;
  tx_ctx.go_callback = goStreamWriteCallback;
  tx_ctx.current_pts = 0.0;
  __atomic_store_n(&tx_ctx.suppress_output, 0, __ATOMIC_RELEASE);

  // Initialize in-memory fMP4 muxer
  ret = init_fmp4_muxer(&out_fmt_ctx, &tx_ctx);
  if (ret < 0)
  {
    LOG_FFMPEG_ERR("C-MUX", "Failed to initialize fMP4 muxer", ret);
    return ret;
  }

  // FORCE SHIFT NEGATIVE PTS/DTS TO ZERO
  // Resolves negative pre-roll timestamps (e.g. Opus/AAC pts < 0) crashing WebKit MSE
  av_opt_set(out_fmt_ctx, "avoid_negative_ts", "make_non_negative", 0);

  // 1. Mux Video Stream
  //    - Passthrough when the source is already H.264 (zero CPU / zero quality loss)
  //    - Otherwise force a highly compatible H.264 re-encode so every file plays in
  //      Chrome / Edge / Safari MSE.
  if (dec_ctx->video_stream_idx >= 0 && dec_ctx->video_dec_ctx)
  {
    need_video_reencode = (dec_ctx->video_dec_ctx->codec_id != AV_CODEC_ID_H264);

    if (!need_video_reencode)
    {
      // Fast path – pure passthrough
      AVStream *in_stream = dec_ctx->fmt_ctx->streams[dec_ctx->video_stream_idx];
      AVStream *out_stream = avformat_new_stream(out_fmt_ctx, NULL);
      if (!out_stream)
      {
        LOG_ERROR("C-MUX", "Failed to allocate new video stream for passthrough");
        free_fmp4_muxer(out_fmt_ctx);
        return AVERROR(ENOMEM);
      }
      ret = avcodec_parameters_copy(out_stream->codecpar, in_stream->codecpar);
      if (ret < 0)
      {
        LOG_FFMPEG_ERR("C-MUX", "Failed to copy video parameters", ret);
        free_fmp4_muxer(out_fmt_ctx);
        return ret;
      }
      out_stream->codecpar->codec_tag = 0;
      out_video_idx = out_stream->index;
    }
    else
    {
      // Slow path – force H.264 (Baseline/Main, low-latency, GLOBAL_HEADER)
      ret = init_h264_encoder(dec_ctx, &h264_enc_ctx);
      if (ret < 0)
      {
        LOG_FFMPEG_ERR("C-MUX", "Failed to initialize H.264 encoder – no usable encoder/resolution combination", ret);
        free_fmp4_muxer(out_fmt_ctx);
        return ret;
      }

      AVStream *out_stream = avformat_new_stream(out_fmt_ctx, NULL);
      if (!out_stream)
      {
        LOG_ERROR("C-MUX", "Failed to allocate new video stream for encoding");
        avcodec_free_context(&h264_enc_ctx);
        free_fmp4_muxer(out_fmt_ctx);
        return AVERROR(ENOMEM);
      }
      ret = avcodec_parameters_from_context(out_stream->codecpar, h264_enc_ctx);
      if (ret < 0)
      {
        LOG_FFMPEG_ERR("C-MUX", "Failed to copy H.264 parameters to stream", ret);
        avcodec_free_context(&h264_enc_ctx);
        free_fmp4_muxer(out_fmt_ctx);
        return ret;
      }
      out_stream->codecpar->codec_tag = 0;
      out_video_idx = out_stream->index;

      // Determine valid software pixel formats for input/output to avoid HWACCEL format errors
      enum AVPixelFormat init_src_fmt = dec_ctx->video_dec_ctx->pix_fmt;
      if (dec_ctx->video_dec_ctx->sw_pix_fmt != AV_PIX_FMT_NONE)
      {
        init_src_fmt = dec_ctx->video_dec_ctx->sw_pix_fmt;
      }
      else
      {
        const AVPixFmtDescriptor *src_desc = av_pix_fmt_desc_get(init_src_fmt);
        if (src_desc && (src_desc->flags & AV_PIX_FMT_FLAG_HWACCEL))
          init_src_fmt = AV_PIX_FMT_YUV420P;
      }

      enum AVPixelFormat init_dst_fmt = h264_enc_ctx->pix_fmt;
      const AVPixFmtDescriptor *dst_desc = av_pix_fmt_desc_get(init_dst_fmt);
      if (dst_desc && (dst_desc->flags & AV_PIX_FMT_FLAG_HWACCEL))
      {
        init_dst_fmt = (h264_enc_ctx->sw_pix_fmt != AV_PIX_FMT_NONE) ? h264_enc_ctx->sw_pix_fmt : AV_PIX_FMT_NV12;
      }

      // Colour-space converter (any decoder output -> target software pixel format)
      // Prefer higher quality when source is HDR or we are significantly downscaling.
      int sws_flags = SWS_FAST_BILINEAR;
      bool hdr = is_hdr_source(dec_ctx->video_dec_ctx);

      if (hdr ||
          dec_ctx->video_dec_ctx->width > h264_enc_ctx->width * 1.5 ||
          dec_ctx->video_dec_ctx->height > h264_enc_ctx->height * 1.5)
      {
        sws_flags = SWS_BICUBIC;
      }

      sws_ctx = sws_getContext(
          dec_ctx->video_dec_ctx->width, dec_ctx->video_dec_ctx->height,
          init_src_fmt,
          h264_enc_ctx->width, h264_enc_ctx->height, init_dst_fmt,
          sws_flags, NULL, NULL, NULL);

      if (!sws_ctx)
      {
        LOG_ERROR("C-MUX", "Failed to allocate sws_ctx for color conversion");
        ret = AVERROR(ENOMEM);
        goto cleanup;
      }

      // Configure explicit color matrix mapping (crucial for HDR / BT.2020 -> BT.709 conversion)
      int src_range = (dec_ctx->video_dec_ctx->color_range == AVCOL_RANGE_JPEG);
      const int *src_inv_table = sws_getCoefficients(sws_coeff_id_from_colorspace(dec_ctx->video_dec_ctx->colorspace));
      const int *dst_inv_table = sws_getCoefficients(SWS_CS_ITU709);
      sws_setColorspaceDetails(sws_ctx, src_inv_table, src_range, dst_inv_table, 0, 0, 1 << 16, 1 << 16);

      if (hdr)
      {
        LOG_INFO("C-ENC", "HDR source detected at init (primaries/trc). "
                          "Using higher-quality scaler + BT.2020→BT.709 matrix. "
                          "Full PQ/HLG tone-map requires zscale/libplacebo (future).");
      }

      enc_video_frame = av_frame_alloc();
      if (!enc_video_frame)
      {
        LOG_ERROR("C-MUX", "Failed to allocate enc_video_frame");
        ret = AVERROR(ENOMEM);
        goto cleanup;
      }
      enc_video_frame->format = init_dst_fmt;
      enc_video_frame->width = h264_enc_ctx->width;
      enc_video_frame->height = h264_enc_ctx->height;

      ret = av_frame_get_buffer(enc_video_frame, 32);
      if (ret < 0)
      {
        LOG_FFMPEG_ERR("C-MUX", "Failed to allocate buffer for enc_video_frame", ret);
        goto cleanup;
      }

      enc_video_pkt = av_packet_alloc();
      if (!enc_video_pkt)
      {
        LOG_ERROR("C-MUX", "Failed to allocate enc_video_pkt");
        ret = AVERROR(ENOMEM);
        goto cleanup;
      }
    }
  }

  // 2. Setup Audio Stream (Passthrough if AAC/MP3, otherwise Transcode to AAC)
  if (dec_ctx->audio_stream_idx >= 0)
  {
    AVCodecParameters *a_par = dec_ctx->fmt_ctx->streams[dec_ctx->audio_stream_idx]->codecpar;
    audio_needs_transcode = (a_par->codec_id != AV_CODEC_ID_AAC && a_par->codec_id != AV_CODEC_ID_OPUS);

    if (!audio_needs_transcode)
    {
      // Fast path – direct passthrough for MSE-compatible audio (AAC / MP3)
      AVStream *in_stream = dec_ctx->fmt_ctx->streams[dec_ctx->audio_stream_idx];
      AVStream *out_stream = avformat_new_stream(out_fmt_ctx, NULL);
      if (!out_stream)
      {
        LOG_ERROR("C-MUX", "Failed to allocate new audio stream for passthrough");
        ret = AVERROR(ENOMEM);
        goto cleanup;
      }
      ret = avcodec_parameters_copy(out_stream->codecpar, in_stream->codecpar);
      if (ret < 0)
      {
        LOG_FFMPEG_ERR("C-MUX", "Failed to copy audio parameters", ret);
        goto cleanup;
      }
      out_stream->codecpar->codec_tag = 0;
      out_audio_idx = out_stream->index;
    }
    else
    {
      // Slow path – transcode non-MSE audio (e.g. PCM, FLAC, Vorbis) to AAC
      const AVCodec *aac_codec = avcodec_find_encoder(AV_CODEC_ID_AAC);
      if (aac_codec)
      {
        aac_enc_ctx = avcodec_alloc_context3(aac_codec);
        if (!aac_enc_ctx)
        {
          LOG_ERROR("C-MUX", "Failed to allocate AAC encoding context");
          ret = AVERROR(ENOMEM);
          goto cleanup;
        }
        aac_enc_ctx->sample_rate = 48000;
        av_channel_layout_default(&aac_enc_ctx->ch_layout, 2);
        aac_enc_ctx->sample_fmt = AV_SAMPLE_FMT_FLTP;
        aac_enc_ctx->bit_rate = 192000;
        aac_enc_ctx->time_base = (AVRational){1, 48000};   // Required for smooth MSE sync
        aac_enc_ctx->flags |= AV_CODEC_FLAG_GLOBAL_HEADER; // Essential for MSE AAC extradata

        ret = avcodec_open2(aac_enc_ctx, aac_codec, NULL);
        if (ret >= 0)
        {
          AVStream *out_stream = avformat_new_stream(out_fmt_ctx, NULL);
          if (!out_stream)
          {
            LOG_ERROR("C-MUX", "Failed to allocate new audio stream");
            ret = AVERROR(ENOMEM);
            goto cleanup;
          }
          out_audio_idx = out_stream->index;

          ret = avcodec_parameters_from_context(out_stream->codecpar, aac_enc_ctx);
          if (ret < 0)
          {
            LOG_FFMPEG_ERR("C-MUX", "Failed to copy AAC parameters to stream", ret);
            goto cleanup;
          }
          out_stream->codecpar->codec_tag = 0;

          // FFmpeg AAC strict frame size enforcement (1024 frames)
          fifo = av_audio_fifo_alloc(aac_enc_ctx->sample_fmt, 2, 32768);
          if (!fifo)
          {
            LOG_ERROR("C-MUX", "Failed to allocate audio FIFO");
            ret = AVERROR(ENOMEM);
            goto cleanup;
          }

          enc_frame = av_frame_alloc();
          if (!enc_frame)
          {
            LOG_ERROR("C-MUX", "Failed to allocate AAC encoder frame");
            ret = AVERROR(ENOMEM);
            goto cleanup;
          }
          enc_frame->nb_samples = aac_enc_ctx->frame_size;
          enc_frame->format = aac_enc_ctx->sample_fmt;
          av_channel_layout_copy(&enc_frame->ch_layout, &aac_enc_ctx->ch_layout);

          ret = av_frame_get_buffer(enc_frame, 0);
          if (ret < 0)
          {
            LOG_FFMPEG_ERR("C-MUX", "Failed to allocate buffer for AAC frame", ret);
            goto cleanup;
          }

          enc_pkt = av_packet_alloc();
          if (!enc_pkt)
          {
            LOG_ERROR("C-MUX", "Failed to allocate AAC encoder packet");
            ret = AVERROR(ENOMEM);
            goto cleanup;
          }

          // Static buffer for intermediate SWR conversions (up to 8192 samples per read)
          ret = av_samples_alloc(resample_buf, NULL, 2, 8192, AV_SAMPLE_FMT_FLTP, 0);
          if (ret < 0)
          {
            LOG_FFMPEG_ERR("C-MUX", "Failed to allocate audio resample buffer", ret);
            goto cleanup;
          }
        }
        else
        {
          LOG_FFMPEG_ERR("C-MUX", "Failed to open AAC encoder", ret);
          goto cleanup;
        }
      }
      else
      {
        LOG_ERROR("C-MUX", "AAC encoder not found in FFmpeg build");
      }
    }
  }

  ret = write_fmp4_header(out_fmt_ctx);
  if (ret < 0)
  {
    LOG_FFMPEG_ERR("C-MUX", "Failed to write initial fMP4 header", ret);
    goto cleanup; // Ensures any audio resources allocated above are freed
  }

  pkt = av_packet_alloc();
  frame = av_frame_alloc();
  if (!pkt || !frame)
  {
    LOG_ERROR("C-MUX", "Failed to allocate main loop packet/frame");
    ret = AVERROR(ENOMEM);
    goto cleanup;
  }

  // CRITICAL: Real-time pacing variables.
  // Track the exact microsecond the stream starts + accumulated pause time so we
  // never deliver more than READ_AHEAD_US (20 s) of future media.
  int64_t stream_start_time_us = av_gettime_relative();
  int64_t total_pause_us = 0;
  int64_t current_pause_start_us = 0;
  const int64_t READ_AHEAD_US = 20000000LL; // 20 seconds of runway (prevents 8K keyframe stalls)
  int just_seeked = 0;
  int eof_reached = 0;      // Tracks if we hit the end of the file
  int pipeline_flushed = 0; // Tracks if we drained the trapped encoder frames
  int trailer_written = 0;  // Track if the last fMP4 fragment has been flushed

  LOG_INFO("C-MUX", "Entering main streaming pipeline loop");

  // Main streaming loop — designed to stay alive and react to control signals.
  while (true)
  {
    // Check control flags from Go side (Option 3 style)
    // Atomic loads for thread-safety. The Go control thread (ControlStream)
    // can set these flags at any time without locking the entire pipeline.
    if (__atomic_load_n(&dec_ctx->stop_requested, __ATOMIC_ACQUIRE))
    {
      LOG_DEBUG("C-MUX", "Stop requested from Go routine. Exiting pipeline.");
      break;
    }

    if (__atomic_load_n(&dec_ctx->seek_requested, __ATOMIC_ACQUIRE))
    {
      int64_t target_ms = __atomic_load_n(&dec_ctx->seek_target_ms, __ATOMIC_ACQUIRE);
      // Perform seek on the format context + flush decoders.
      // Safe because we do it from inside the read-loop thread,
      // avoiding race conditions with av_read_frame.
      int64_t seek_target = (int64_t)(target_ms * (int64_t)AV_TIME_BASE / 1000);
      int stream_idx = dec_ctx->video_stream_idx >= 0 ? dec_ctx->video_stream_idx : -1;

      // CRITICAL FIX: Convert the microsecond target into the specific stream's timebase units
      if (stream_idx >= 0)
      {
        seek_target = av_rescale_q(seek_target, AV_TIME_BASE_Q, dec_ctx->fmt_ctx->streams[stream_idx]->time_base);
      }

      int seek_ret = av_seek_frame(dec_ctx->fmt_ctx, stream_idx, seek_target, AVSEEK_FLAG_BACKWARD);
      if (seek_ret >= 0)
      {
        LOG_INFO("C-SEEK", "Executing backward seek to ms: %lld", (long long)target_ms);

        wait_for_video_keyframe = (dec_ctx->video_stream_idx >= 0) ? 1 : 0;

        // Reset audio FIFO and flush trapped decoder frames immediately
        if (fifo)
        {
          av_audio_fifo_reset(fifo);
        }

        // Flush video decoders
        if (dec_ctx->video_dec_ctx)
          avcodec_flush_buffers(dec_ctx->video_dec_ctx);

        // CRITICAL FIX: Recreate the H.264 Encoder
        // Calling avcodec_flush_buffers on libx264 permanently stops its lookahead thread.
        // We must destroy and recreate it to prevent terminal encoder failure.
        if (need_video_reencode && h264_enc_ctx)
        {
          avcodec_free_context(&h264_enc_ctx);
          if (init_h264_encoder(dec_ctx, &h264_enc_ctx) < 0)
          {
            LOG_ERROR("C-SEEK", "Failed to recreate H.264 encoder after seek");
            __atomic_store_n(&dec_ctx->stop_requested, 1, __ATOMIC_RELEASE);
          }
        }

        // Flush Audio decoders and FIFO
        if (dec_ctx->audio_dec_ctx)
          avcodec_flush_buffers(dec_ctx->audio_dec_ctx);
        if (fifo)
          av_audio_fifo_reset(fifo);

        // CRITICAL FIX: Recreate the AAC Encoder
        // Native AAC encoder does not reset its internal PTS tracker on flush.
        // We must destroy and recreate it to prevent "Queue input is backward in time"
        // and fatal DTS monotonicity errors inside the newly spawned muxer.
        if (aac_enc_ctx)
        {
          avcodec_free_context(&aac_enc_ctx);

          const AVCodec *aac_codec = avcodec_find_encoder(AV_CODEC_ID_AAC);
          if (aac_codec)
          {
            aac_enc_ctx = avcodec_alloc_context3(aac_codec);
            if (aac_enc_ctx)
            {
              aac_enc_ctx->sample_rate = 48000;
              av_channel_layout_default(&aac_enc_ctx->ch_layout, 2);
              aac_enc_ctx->sample_fmt = AV_SAMPLE_FMT_FLTP;
              aac_enc_ctx->bit_rate = 192000;
              aac_enc_ctx->time_base = (AVRational){1, 48000};
              aac_enc_ctx->flags |= AV_CODEC_FLAG_GLOBAL_HEADER;

              if (avcodec_open2(aac_enc_ctx, aac_codec, NULL) < 0)
              {
                LOG_ERROR("C-SEEK", "Failed to reopen AAC encoder after seek");
              }
            }
          }
        }

        // Keep the original media clock. AAC time_base is 1/48000.
        audio_pts_counter = target_ms * 48;

        // Recreate the fMP4 muxer to reset FFmpeg DTS trackers.
        // The new ftyp/moov must not be forwarded to MSE (SourceBuffer is already initialized).
        if (out_fmt_ctx)
        {
          free_fmp4_muxer(out_fmt_ctx);
          out_fmt_ctx = NULL;
        }

        if (init_fmp4_muxer(&out_fmt_ctx, &tx_ctx) < 0)
        {
          LOG_ERROR("C-SEEK", "Failed to re-initialize fMP4 muxer after seek");
        }

        if (out_fmt_ctx)
        {
          av_opt_set(out_fmt_ctx, "avoid_negative_ts", "make_non_negative", 0);
        }

        // Reset the trailer flag for the new muxer session
        trailer_written = 0;

        // Re-map the video stream into the new muxer
        if (dec_ctx->video_stream_idx >= 0 && out_fmt_ctx)
        {
          AVStream *out_stream = avformat_new_stream(out_fmt_ctx, NULL);
          if (out_stream)
          {
            if (!need_video_reencode)
            {
              if (avcodec_parameters_copy(out_stream->codecpar, dec_ctx->fmt_ctx->streams[dec_ctx->video_stream_idx]->codecpar) < 0)
              {
                LOG_ERROR("C-SEEK", "Failed to map video parameters to new muxer");
              }
            }
            else if (h264_enc_ctx)
            {
              if (avcodec_parameters_from_context(out_stream->codecpar, h264_enc_ctx) < 0)
              {
                LOG_ERROR("C-SEEK", "Failed to map H.264 parameters to new muxer");
              }
            }
            out_stream->codecpar->codec_tag = 0;
            out_video_idx = out_stream->index;
          }
        }

        // Re-map the audio stream into the new muxer after seek
        if (dec_ctx->audio_stream_idx >= 0 && out_fmt_ctx)
        {
          AVStream *out_stream = avformat_new_stream(out_fmt_ctx, NULL);
          if (out_stream)
          {
            if (!audio_needs_transcode)
            {
              // Re-map passthrough audio stream parameters directly
              if (avcodec_parameters_copy(out_stream->codecpar, dec_ctx->fmt_ctx->streams[dec_ctx->audio_stream_idx]->codecpar) < 0)
              {
                LOG_ERROR("C-SEEK", "Failed to map audio parameters to new muxer");
              }
            }
            else if (aac_enc_ctx)
            {
              // Re-map transcoded AAC encoder stream parameters
              if (avcodec_parameters_from_context(out_stream->codecpar, aac_enc_ctx) < 0)
              {
                LOG_ERROR("C-SEEK", "Failed to map AAC parameters to new muxer");
              }
            }
            out_stream->codecpar->codec_tag = 0;
            out_audio_idx = out_stream->index;
          }
        }

        // Write header to satisfy the new muxer, but swallow it so MSE does not
        // receive a second init segment.
        if (out_fmt_ctx)
        {
          __atomic_store_n(&tx_ctx.suppress_output, 1, __ATOMIC_RELEASE);

          if (write_fmp4_header(out_fmt_ctx) < 0)
          {
            LOG_ERROR("C-SEEK", "Failed to write fMP4 header after seek");
          }

          if (out_fmt_ctx->pb)
            avio_flush(out_fmt_ctx->pb);

          __atomic_store_n(&tx_ctx.suppress_output, 0, __ATOMIC_RELEASE);
        }

        // CRITICAL: Reset wall-clock baseline so the throttle aligns with the new seek position
        stream_start_time_us = av_gettime_relative() - (target_ms * 1000LL);
        total_pause_us = 0;
        current_pause_start_us = 0;
        just_seeked = 1;
        eof_reached = 0;      // Reset EOF flag on seek
        pipeline_flushed = 0; // Reset flush flag on seek
        // Reset Go-side EOF state for new timeline
        set_session_eof(tx_ctx.go_user_token, 0);
        __atomic_store_n(&dec_ctx->backpressure_paused, 0, __ATOMIC_RELEASE);

        LOG_INFO("C-SEEK", "Seek to %lld ms succeeded (absolute PTS preserved).", (long long)target_ms);
      }
      else
      {
        LOG_FFMPEG_ERR("C-SEEK", "AVSeek execution failed", seek_ret);
      }

      // Clear the lock flag so the loop proceeds
      __atomic_store_n(&dec_ctx->seek_requested, 0, __ATOMIC_RELEASE);
      continue;
    }

    int user_paused = __atomic_load_n(&dec_ctx->paused, __ATOMIC_ACQUIRE);
    int bp_paused = __atomic_load_n(&dec_ctx->backpressure_paused, __ATOMIC_ACQUIRE);

    if (bp_paused || (user_paused && !just_seeked))
    {
      // Track exactly how long we are paused so we don't burst data when resumed
      if (current_pause_start_us == 0)
        current_pause_start_us = av_gettime_relative();
      av_usleep(20000);
      continue;
    }
    else if (current_pause_start_us > 0)
    {
      // Add the duration of the pause to our total offset and reset
      total_pause_us += (av_gettime_relative() - current_pause_start_us);
      current_pause_start_us = 0;
    }

    if (!eof_reached)
    {
      ret = av_read_frame(dec_ctx->fmt_ctx, pkt);
      if (ret == AVERROR_EOF)
      {
        LOG_INFO("C-READ", "EOF reached. Preparing to flush trapped frames.");
        eof_reached = 1;
      }
      else if (ret < 0)
      {
        LOG_FFMPEG_ERR("C-READ", "Fatal frame read error", ret);
        break; // Break only on fatal I/O crashes, not EOF
      }
    }

    if (eof_reached && !pipeline_flushed)
    {
      // Flush the H.264 Encoder to extract the final trapped video frames
      if (need_video_reencode && h264_enc_ctx)
      {
        avcodec_send_frame(h264_enc_ctx, NULL); // return value intentionally ignored on flush
        while (avcodec_receive_packet(h264_enc_ctx, enc_video_pkt) >= 0)
        {
          av_packet_rescale_ts(enc_video_pkt, h264_enc_ctx->time_base, out_fmt_ctx->streams[out_video_idx]->time_base);
          enc_video_pkt->stream_index = out_video_idx;
          if (av_interleaved_write_frame(out_fmt_ctx, enc_video_pkt) < 0)
          {
            LOG_WARN("C-MUX", "Failed to write flushed video packet");
          }
          av_packet_unref(enc_video_pkt);
        }
      }

      // Flush the AAC Encoder to extract the final trapped audio packets
      if (aac_enc_ctx)
      {
        avcodec_send_frame(aac_enc_ctx, NULL); // Intentional ignore on flush
        while (avcodec_receive_packet(aac_enc_ctx, enc_pkt) >= 0)
        {
          av_packet_rescale_ts(enc_pkt, aac_enc_ctx->time_base, out_fmt_ctx->streams[out_audio_idx]->time_base);
          enc_pkt->stream_index = out_audio_idx;
          if (av_interleaved_write_frame(out_fmt_ctx, enc_pkt) < 0)
          {
            LOG_WARN("C-MUX", "Failed to write flushed audio packet");
          }
          av_packet_unref(enc_pkt);
        }
      }

      pipeline_flushed = 1;

      // Force the muxer to flush the final trapped frames
      if (out_fmt_ctx && !trailer_written)
      {
        int trail_ret = av_write_trailer(out_fmt_ctx);
        if (trail_ret < 0)
        {
          LOG_FFMPEG_ERR("C-MUX", "Failed to write fMP4 trailer at EOF", trail_ret);
        }
        trailer_written = 1;
      }

      // CRITICAL: Notify Go that all trailing packets from this point forward are EOF
      extern void set_session_eof(uintptr_t token, int is_eof);
      set_session_eof(tx_ctx.go_user_token, 1);

      LOG_INFO("C-EOF", "Pipeline flushed successfully. Final frames sent to browser. Idling for seeks.");
    }

    // If we are at the end of the file and flushed, keep the pipeline alive for backward seeks
    if (eof_reached && pipeline_flushed)
    {
      av_usleep(100000); // Sleep for 100ms
      continue;          // Bypass the rest of the loop and wait for a control signal
    }

    if (ret >= 0)
    {
      LOG_DEBUG("C-READ", "stream=%d pts=%lld", pkt->stream_index, (long long)pkt->pts);
    }

    if (wait_for_video_keyframe && dec_ctx->video_stream_idx >= 0)
    {
      if (pkt->stream_index == dec_ctx->video_stream_idx)
      {
        if (pkt->flags & AV_PKT_FLAG_KEY)
        {
          wait_for_video_keyframe = 0; // Keyframe found; open the pipeline
        }
        else
        {
          av_packet_unref(pkt);
          continue; // Drop lead-in non-keyframe video packets
        }
      }
      else
      {
        av_packet_unref(pkt);
        continue; // Drop lead-in audio packets prior to the keyframe
      }
    }

    // VIDEO PATH
    if (pkt->stream_index == dec_ctx->video_stream_idx && out_video_idx >= 0)
    {
      // Interleaving guard: Force audio FIFO conversion pass before writing video frames
      if (audio_needs_transcode && fifo && aac_enc_ctx)
      {
        // Flush queued audio FIFO samples to keep A/V DTS strictly interleaved in fMP4 fragments
        while (av_audio_fifo_size(fifo) >= aac_enc_ctx->frame_size)
        {
          if (av_audio_fifo_read(fifo, (void **)enc_frame->data, aac_enc_ctx->frame_size) >= 0)
          {
            if (audio_pts_counter < 0)
              audio_pts_counter = 0;
            enc_frame->pts = audio_pts_counter;
            audio_pts_counter += aac_enc_ctx->frame_size;

            if (avcodec_send_frame(aac_enc_ctx, enc_frame) >= 0)
            {
              while (avcodec_receive_packet(aac_enc_ctx, enc_pkt) >= 0)
              {
                av_packet_rescale_ts(enc_pkt, aac_enc_ctx->time_base, out_fmt_ctx->streams[out_audio_idx]->time_base);
                enc_pkt->stream_index = out_audio_idx;
                av_interleaved_write_frame(out_fmt_ctx, enc_pkt);
                av_packet_unref(enc_pkt);
              }
            }
          }
        }
      }

      if (!need_video_reencode)
      {
        // Passthrough (original path)
        AVStream *in_stream = dec_ctx->fmt_ctx->streams[dec_ctx->video_stream_idx];
        AVStream *out_stream = out_fmt_ctx->streams[out_video_idx];

        double calculated_pts = pkt->pts != AV_NOPTS_VALUE
                                    ? pkt->pts * av_q2d(in_stream->time_base)
                                    : 0.0;
        int64_t pkt_time_us = (int64_t)(calculated_pts * 1000000.0);

        extern void set_session_pts(uintptr_t token, double pts);
        set_session_pts(tx_ctx.go_user_token, calculated_pts);

        // CRITICAL: Real-time pacing lock.
        // Forces the C pipeline to sleep if it is generating data faster than
        // the real-world clock (plus our 20-second buffer allowance).
        // Also aborts the wait immediately on any control signal.
        int interrupted = 0;

        if (just_seeked)
        {
          // Force a keyframe on the first frame after a seek:
          frame->pict_type = AV_PICTURE_TYPE_I;

          // First packet after a seek -> force the clock to match reality
          // so we don't sleep for minutes
          stream_start_time_us = av_gettime_relative() - pkt_time_us;
          just_seeked = 0;
        }
        else
        {
          while (true)
          {
            if (__atomic_load_n(&dec_ctx->stop_requested, __ATOMIC_ACQUIRE) ||
                __atomic_load_n(&dec_ctx->seek_requested, __ATOMIC_ACQUIRE) ||
                __atomic_load_n(&dec_ctx->paused, __ATOMIC_ACQUIRE))
            {
              interrupted = 1;
              break;
            }

            int64_t elapsed_us = av_gettime_relative() - stream_start_time_us - total_pause_us;
            if (pkt_time_us > elapsed_us + READ_AHEAD_US)
              // Sleep and re-evaluate the clock
              // Reduced to 5ms sleep for high responsiveness
              av_usleep(5000);
            else
              break; // Clock has caught up – proceed with remuxing
          }
        }

        // CRITICAL: Immediately re-check if we broke because of a seek request
        if (__atomic_load_n(&dec_ctx->seek_requested, __ATOMIC_ACQUIRE))
        {
          av_packet_unref(pkt);
          continue; // Jump back to the top of the while(true) loop to execute the seek
        }

        // Only write if the throttle was not interrupted by a control signal.
        // (Writing an outdated packet after a seek would corrupt the timeline.)
        if (!interrupted)
        {
          av_packet_rescale_ts(pkt, in_stream->time_base, out_stream->time_base);
          pkt->stream_index = out_video_idx;

          // Catch fatal container formatting errors instead of feeding garbage to the browser
          LOG_DEBUG("C-MUX", "Writing VIDEO packet pts=%lld size=%d",
                    (long long)pkt->pts, pkt->size);

          if (av_interleaved_write_frame(out_fmt_ctx, pkt) < 0)
          {
            LOG_ERROR("C-MUX", "Failed to write interleaved video packet (passthrough). Halting.");
            __atomic_store_n(&dec_ctx->stop_requested, 1, __ATOMIC_RELEASE);
          }
        }
      }
      else
      {
        // Full H.264 re-encode path (with real-time pacing, hardware-to-system frame transfer, and dynamic sws context)

        // Post-seek keyframe guard for decoder:
        // Do not feed non-keyframes into a flushed decoder post-seek
        if (just_seeked)
        {
          if (!(pkt->flags & AV_PKT_FLAG_KEY))
          {
            av_packet_unref(pkt);
            continue; // Skip non-keyframe packets until the first valid IDR frame
          }
        }

        if (avcodec_send_packet(dec_ctx->video_dec_ctx, pkt) >= 0)
        {
          // CRITICAL FIX: Track the seek interrupt for the outer loop
          int seek_interrupted = 0;

          while (avcodec_receive_frame(dec_ctx->video_dec_ctx, frame) >= 0)
          {
            AVFrame *sw_frame = frame;

            // Check if zero-copy GPU hardware acceleration pipeline is active (cross-platform matching)
            const AVPixFmtDescriptor *frame_desc = av_pix_fmt_desc_get(frame->format);
            bool is_hw_frame = (frame_desc && (frame_desc->flags & AV_PIX_FMT_FLAG_HWACCEL));
            bool is_direct_gpu_pass = (is_hw_frame &&
                                       frame->format == h264_enc_ctx->pix_fmt &&
                                       frame->width == h264_enc_ctx->width &&
                                       frame->height == h264_enc_ctx->height);

            // One-time path logging
            static int logged_zerocopy = 0;
            static int logged_swpath = 0;

            if (is_direct_gpu_pass)
            {
              if (!logged_zerocopy)
              {
                LOG_INFO("C-ENC", "Zero-copy HW surface path active (encoder accepts decoder surface)");
                logged_zerocopy = 1;
              }
            }
            else
            {
              if (!logged_swpath)
              {
                LOG_INFO("C-ENC", "Software path active (HW transfer + sws_scale required)");
                logged_swpath = 1;
              }
            }

            if (!is_direct_gpu_pass)
            {
              // 1. Generic Hardware Surface Check:
              // Transfer GPU hardware surface frames (VideoToolbox / D3D11 / VAAPI / CUDA)
              // into CPU system memory so sws_scale can access valid pixel memory pointers.
              if (is_hw_frame)
              {
                AVFrame *cpu_frame = av_frame_alloc();
                if (cpu_frame)
                {
                  if (av_hwframe_transfer_data(cpu_frame, frame, 0) >= 0)
                  {
                    cpu_frame->pts = frame->pts;
                    cpu_frame->pict_type = frame->pict_type;
                    sw_frame = cpu_frame;
                  }
                  else
                  {
                    av_frame_free(&cpu_frame);
                  }
                }
              }
            }

            // Convert PTS from the input stream time_base -> encoder time_base
            AVStream *in_stream = dec_ctx->fmt_ctx->streams[dec_ctx->video_stream_idx];

            // Real-time pacing (identical logic to the passthrough path)
            double calculated_pts = sw_frame->pts != AV_NOPTS_VALUE
                                        ? sw_frame->pts * av_q2d(in_stream->time_base)
                                        : 0.0;
            int64_t pkt_time_us = (int64_t)(calculated_pts * 1000000.0);

            extern void set_session_pts(uintptr_t token, double pts);
            set_session_pts(tx_ctx.go_user_token, calculated_pts);

            int interrupted = 0;

            if (just_seeked)
            {
              // First packet after a seek -> force the clock to match reality
              // so we don't sleep for minutes
              stream_start_time_us = av_gettime_relative() - pkt_time_us;
              just_seeked = 0;
            }
            else
            {
              while (true)
              {
                if (__atomic_load_n(&dec_ctx->stop_requested, __ATOMIC_ACQUIRE) ||
                    __atomic_load_n(&dec_ctx->seek_requested, __ATOMIC_ACQUIRE) ||
                    __atomic_load_n(&dec_ctx->paused, __ATOMIC_ACQUIRE))
                {
                  interrupted = 1;
                  break;
                }

                int64_t elapsed_us = av_gettime_relative() - stream_start_time_us - total_pause_us;
                if (pkt_time_us > elapsed_us + READ_AHEAD_US)
                  av_usleep(5000);
                else
                  break;
              }
            }

            // CRITICAL FIX: Break the inner frame loop immediately
            if (__atomic_load_n(&dec_ctx->seek_requested, __ATOMIC_ACQUIRE))
            {
              if (sw_frame != frame)
                av_frame_free(&sw_frame);
              seek_interrupted = 1;
              break;
            }

            if (interrupted)
            {
              if (sw_frame != frame)
                av_frame_free(&sw_frame);
              continue; // Skip encoding this frame if paused/stopped
            }

            AVFrame *frame_to_encode = NULL;

            if (is_direct_gpu_pass)
            {
              // ZERO-COPY GPU PATH: Pass native hardware surface directly.
              // Hardware encoder automatically performs GPU-accelerated scaling and encoding.
              frame_to_encode = frame;
              frame_to_encode->pts = av_rescale_q(frame->pts,
                                                  in_stream->time_base,
                                                  h264_enc_ctx->time_base);
            }
            else
            {
              // Resolve software destination pixel format for encoder
              enum AVPixelFormat dst_pix_fmt = h264_enc_ctx->pix_fmt;
              const AVPixFmtDescriptor *enc_desc = av_pix_fmt_desc_get(dst_pix_fmt);
              if (enc_desc && (enc_desc->flags & AV_PIX_FMT_FLAG_HWACCEL))
              {
                dst_pix_fmt = (h264_enc_ctx->sw_pix_fmt != AV_PIX_FMT_NONE) ? h264_enc_ctx->sw_pix_fmt : AV_PIX_FMT_NV12;
                // Synchronize encoder context pixel format when operating on software fallback frames
                h264_enc_ctx->pix_fmt = dst_pix_fmt;
              }

              // Ensure enc_video_frame buffer matches dst_pix_fmt
              if (enc_video_frame->format != dst_pix_fmt)
              {
                av_frame_unref(enc_video_frame);
                enc_video_frame->format = dst_pix_fmt;
                enc_video_frame->width = h264_enc_ctx->width;
                enc_video_frame->height = h264_enc_ctx->height;
                if (av_frame_get_buffer(enc_video_frame, 32) < 0)
                {
                  LOG_ERROR("C-MUX", "Failed to re-allocate buffer for enc_video_frame");
                }
              }

              // 2. Dynamic Scale Context Management with Direct Color Conversion
              // Prefer higher quality when source is HDR or we are downscaling a lot.
              int sws_flags = SWS_FAST_BILINEAR;
              bool hdr = is_hdr_source(dec_ctx->video_dec_ctx);

              if (hdr ||
                  sw_frame->width > h264_enc_ctx->width * 1.5 ||
                  sw_frame->height > h264_enc_ctx->height * 1.5)
              {
                sws_flags = SWS_BICUBIC; /* better quality for HDR / large downscales */
              }

              sws_ctx = sws_getCachedContext(
                  sws_ctx,
                  sw_frame->width, sw_frame->height, sw_frame->format,
                  h264_enc_ctx->width, h264_enc_ctx->height, dst_pix_fmt,
                  sws_flags, NULL, NULL, NULL);

              if (sws_ctx)
              {
                /* Source matrix from the decoder; destination is BT.709 for
                 * 8-bit H.264. Distinct tables avoid the RGB intermediate. */
                int src_range = (dec_ctx->video_dec_ctx->color_range == AVCOL_RANGE_JPEG);
                int dst_range = 0; // MPEG / limited range

                const int *src_table = sws_getCoefficients(
                    sws_coeff_id_from_colorspace(dec_ctx->video_dec_ctx->colorspace));
                const int *dst_table = sws_getCoefficients(SWS_CS_ITU709);

                sws_setColorspaceDetails(sws_ctx,
                                         src_table, src_range,
                                         dst_table, dst_range,
                                         0, 1 << 16, 1 << 16);

                if (hdr)
                {
                  LOG_INFO("C-ENC", "HDR source detected (primaries/trc). "
                                    "Applying BT.2020→BT.709 matrix + higher-quality scaler. "
                                    "Full PQ/HLG tone-map requires zscale/libplacebo (future).");
                }
              }

              // Colour conversion + encode
              int scale_ret = sws_scale(sws_ctx,
                                        (const uint8_t *const *)sw_frame->data, sw_frame->linesize,
                                        0, sw_frame->height,
                                        enc_video_frame->data, enc_video_frame->linesize);
              if (scale_ret < 0)
              {
                LOG_WARN("C-MUX", "Hardware scaling failed for current video frame");
              }

              enc_video_frame->pts = av_rescale_q(sw_frame->pts,
                                                  in_stream->time_base,
                                                  h264_enc_ctx->time_base);
              frame_to_encode = enc_video_frame;
            }

            // CRITICAL FIX: Force IDR Keyframe on the encoder input frame using modern FFmpeg flags
            if (sw_frame->pict_type == AV_PICTURE_TYPE_I)
            {
              frame_to_encode->pict_type = AV_PICTURE_TYPE_I;
              frame_to_encode->flags |= AV_FRAME_FLAG_KEY;
            }
            else
            {
              frame_to_encode->pict_type = AV_PICTURE_TYPE_NONE;
              frame_to_encode->flags &= ~AV_FRAME_FLAG_KEY;
            }

            if (avcodec_send_frame(h264_enc_ctx, frame_to_encode) >= 0)
            {
              while (avcodec_receive_packet(h264_enc_ctx, enc_video_pkt) >= 0)
              {
                av_packet_rescale_ts(enc_video_pkt,
                                     h264_enc_ctx->time_base,
                                     out_fmt_ctx->streams[out_video_idx]->time_base);
                enc_video_pkt->stream_index = out_video_idx;

                LOG_DEBUG("C-MUX", "Writing VIDEO packet pts=%lld size=%d",
                          (long long)enc_video_pkt->pts, enc_video_pkt->size);

                if (av_interleaved_write_frame(out_fmt_ctx, enc_video_pkt) < 0)
                {
                  LOG_ERROR("C-MUX", "Failed to write interleaved encoded video packet. Halting.");
                  __atomic_store_n(&dec_ctx->stop_requested, 1, __ATOMIC_RELEASE);
                }

                av_packet_unref(enc_video_pkt);
              }
            }

            // Cleanup temporary CPU frame mapping if allocated for GPU hardware surface
            if (sw_frame != frame)
            {
              av_frame_free(&sw_frame);
            }
          }

          // CRITICAL FIX: Top-level packet cleanup on seek interrupt (targets the main loop)
          if (seek_interrupted)
          {
            av_packet_unref(pkt);
            continue;
          }
        }
      }
    }

    // AUDIO PATH
    else if (pkt->stream_index == dec_ctx->audio_stream_idx && out_audio_idx >= 0)
    {
      if (!audio_needs_transcode)
      {
        // Fast path – Direct Audio Passthrough (native MSE audio like AAC or MP3)
        AVStream *in_stream = dec_ctx->fmt_ctx->streams[dec_ctx->audio_stream_idx];
        AVStream *out_stream = out_fmt_ctx->streams[out_audio_idx];

        av_packet_rescale_ts(pkt, in_stream->time_base, out_stream->time_base);
        pkt->stream_index = out_audio_idx;

        LOG_DEBUG("C-MUX", "Writing AUDIO packet (passthrough) pts=%lld size=%d",
                  (long long)pkt->pts, pkt->size);

        if (av_interleaved_write_frame(out_fmt_ctx, pkt) < 0)
        {
          LOG_ERROR("C-MUX", "Failed to write interleaved audio packet (passthrough). Halting.");
          __atomic_store_n(&dec_ctx->stop_requested, 1, __ATOMIC_RELEASE);
        }
      }
      else if (aac_enc_ctx && fifo)
      {
        // CRITICAL FIX: Perfect A/V Sync Check
        // Start-of-file only. After seek, audio_pts_counter is already at target*48.
        if (audio_pts_counter < 0 && pkt->pts != AV_NOPTS_VALUE)
        {
          AVStream *in_audio_stream = dec_ctx->fmt_ctx->streams[dec_ctx->audio_stream_idx];
          double pkt_pts_sec = pkt->pts * av_q2d(in_audio_stream->time_base);
          if (pkt_pts_sec < 0.0)
            pkt_pts_sec = 0.0;

          int silence_samples = (int)(pkt_pts_sec * 48000.0);
          if (silence_samples > 0)
          {
            LOG_INFO("C-AUDIO", "[FULL MUX] Pre-padding audio gap with %d silent samples (%.3f sec)",
                     silence_samples, pkt_pts_sec);

            // Zero out planar Float32 channel buffers (IEEE 754 float 0.0f = 0x00)
            memset(resample_buf[0], 0, 8192 * sizeof(float));
            memset(resample_buf[1], 0, 8192 * sizeof(float));

            int samples_remaining = silence_samples;
            while (samples_remaining > 0)
            {
              int chunk = (samples_remaining > 8192) ? 8192 : samples_remaining;
              int realloc_ret = av_audio_fifo_realloc(fifo, av_audio_fifo_size(fifo) + chunk);
              if (realloc_ret < 0)
              {
                LOG_FFMPEG_ERR("C-AUDIO", "[FULL MUX] Failed to reallocate audio FIFO for silence padding", realloc_ret);
                break;
              }
              av_audio_fifo_write(fifo, (void **)resample_buf, chunk);
              samples_remaining -= chunk;
            }
          }

          // Force baseline counter to begin strictly at PTS = 0
          audio_pts_counter = 0;
        }

        if (avcodec_send_packet(dec_ctx->audio_dec_ctx, pkt) >= 0)
        {
          while (avcodec_receive_frame(dec_ctx->audio_dec_ctx, frame) >= 0)
          {
            // Convert to FLTP 48 kHz Stereo
            int out_samples = swr_convert(dec_ctx->swr_ctx, resample_buf, 8192,
                                          (const uint8_t **)frame->data, frame->nb_samples);
            if (out_samples > 0)
            {
              // CRITICAL: Dynamically reallocate the FIFO BEFORE writing.
              // Without this, av_audio_fifo_write silently drops samples once the
              // fixed 8192-sample buffer fills. Dropped samples produce A/V desync
              // that surfaces as MEDIA_ERR_DECODE (Code 3) in the browser.
              int realloc_ret = av_audio_fifo_realloc(fifo, av_audio_fifo_size(fifo) + out_samples);
              if (realloc_ret < 0)
              {
                LOG_FFMPEG_ERR("C-MUX", "Could not reallocate audio FIFO", realloc_ret);
                // Treat as fatal – stop the whole streaming loop cleanly
                __atomic_store_n(&dec_ctx->stop_requested, 1, __ATOMIC_RELEASE);
                goto cleanup;
              }

              int write_ret = av_audio_fifo_write(fifo, (void **)resample_buf, out_samples);
              if (write_ret < 0)
              {
                LOG_FFMPEG_ERR("C-MUX", "Failed to write into audio FIFO", write_ret);
                __atomic_store_n(&dec_ctx->stop_requested, 1, __ATOMIC_RELEASE);
                goto cleanup;
              }
            }

            // Consume from FIFO to feed AAC Encoder (needs exactly frame_size per packet)
            while (av_audio_fifo_size(fifo) >= aac_enc_ctx->frame_size)
            {
              int read_ret = av_audio_fifo_read(fifo, (void **)enc_frame->data, aac_enc_ctx->frame_size);
              if (read_ret < 0)
              {
                LOG_FFMPEG_ERR("C-MUX", "Failed to read from audio FIFO", read_ret);
                break; // Exit FIFO processing loop for this frame cycle
              }

              if (audio_pts_counter < 0)
                audio_pts_counter = 0;
              enc_frame->pts = audio_pts_counter;
              audio_pts_counter += aac_enc_ctx->frame_size;

              if (avcodec_send_frame(aac_enc_ctx, enc_frame) >= 0)
              {
                while (avcodec_receive_packet(aac_enc_ctx, enc_pkt) >= 0)
                {
                  av_packet_rescale_ts(enc_pkt, aac_enc_ctx->time_base,
                                       out_fmt_ctx->streams[out_audio_idx]->time_base);
                  enc_pkt->stream_index = out_audio_idx;

                  LOG_DEBUG("C-MUX", "Writing AUDIO packet pts=%lld size=%d",
                            (long long)enc_pkt->pts, enc_pkt->size);

                  if (av_interleaved_write_frame(out_fmt_ctx, enc_pkt) < 0)
                  {
                    LOG_ERROR("C-MUX", "Failed to write interleaved audio packet. Halting.");
                    __atomic_store_n(&dec_ctx->stop_requested, 1, __ATOMIC_RELEASE);
                  }
                  av_packet_unref(enc_pkt);
                }
              }
            }
          }
        }
      }
    }
    av_packet_unref(pkt);
  }

  // Write trailer to finalize the last fMP4 fragment
  if (out_fmt_ctx && !trailer_written)
  {
    int trail_ret = av_write_trailer(out_fmt_ctx);
    if (trail_ret < 0)
    {
      LOG_FFMPEG_ERR("C-MUX", "Failed to write fMP4 trailer", trail_ret);
    }
  }

cleanup:
  LOG_INFO("C-MUX", "Commencing final teardown of dynamic streaming pipeline structs.");

  if (frame)
    av_frame_free(&frame);
  if (pkt)
    av_packet_free(&pkt);
  if (enc_frame)
    av_frame_free(&enc_frame);
  if (enc_pkt)
    av_packet_free(&enc_pkt);
  if (enc_video_frame)
    av_frame_free(&enc_video_frame);
  if (enc_video_pkt)
    av_packet_free(&enc_video_pkt);
  if (fifo)
    av_audio_fifo_free(fifo);
  if (resample_buf[0])
    av_freep(&resample_buf[0]); // Frees the contiguous memory block
  if (sws_ctx)
    sws_freeContext(sws_ctx);
  if (h264_enc_ctx)
    avcodec_free_context(&h264_enc_ctx);
  if (aac_enc_ctx)
    avcodec_free_context(&aac_enc_ctx);
  if (out_fmt_ctx)
    free_fmp4_muxer(out_fmt_ctx);

  return ret;
}

// Small helpers to set control flags from Go in a clean way

void set_dec_ctx_paused(DemuxDecContext *ctx, int paused)
{
  if (ctx)
  {
    __atomic_store_n(&ctx->paused, paused, __ATOMIC_RELEASE);
  }
}

void request_seek_on_dec_ctx(DemuxDecContext *ctx, int64_t seek_ms)
{
  if (ctx)
  {
    __atomic_store_n(&ctx->seek_target_ms, seek_ms, __ATOMIC_RELEASE);
    __atomic_store_n(&ctx->seek_requested, 1, __ATOMIC_RELEASE);
  }
}

void request_stop_on_dec_ctx(DemuxDecContext *ctx)
{
  if (ctx)
  {
    __atomic_store_n(&ctx->stop_requested, 1, __ATOMIC_RELEASE);
  }
}

void set_dec_ctx_backpressure_paused(DemuxDecContext *ctx, int paused)
{
  if (ctx)
    __atomic_store_n(&ctx->backpressure_paused, paused, __ATOMIC_RELEASE);
}